/**
 * A deleted part stays deleted (SRV-H1).
 *
 * Deleting an agent in the dashboard is a soft delete, and it does not revoke the
 * token or stop the pager running on that machine. `touchAgent` used to set
 * `deletedAt: null` on every activity path, so the next heartbeat - seconds later -
 * silently brought the row back, put it in the roster, and made it a wake recipient
 * again, while the person who deleted it believed it was gone.
 *
 * computeRecipients, the eligibility sweep, and roster all filter `deletedAt`;
 * activity was the one path that undid a removal. These tests pin that shut on the
 * connect-code endpoints (heartbeat, usage) and on the MCP connect path.
 *
 * Deliberate re-add is a different thing and stays allowed: connectAgent upserts
 * with `deletedAt: null` when a part is added again from the dashboard.
 */
import { randomBytes } from 'node:crypto'
import { afterAll, describe, expect, it } from 'vitest'
import { and, eq, isNull } from 'drizzle-orm'
import { agents, projects } from '@relayroom/db'
import postgres from 'postgres'
import { computeRecipients } from '../src/wake/pipeline'
import { makeTestApp, TEST_DATABASE_URL } from './helpers'

const { app, db, bus } = makeTestApp()
const rawSql = postgres(TEST_DATABASE_URL)

afterAll(async () => {
  await bus.close()
  await db.$client.end()
  await rawSql.end()
})

interface Fixture {
  projectId: string
  connectCode: string
  userId: string
  rawToken: <REDACTED>
  agentId: string
}

/** A project with one registered, owned part and a live token for its owner. */
async function fixture(part: string): Promise<Fixture> {
  const sfx = randomBytes(6).toString('hex')
  const userId = `del-user-${sfx}`
  const orgId = `del-org-${sfx}`

  await rawSql`
    INSERT INTO better_auth_oauth_application
      (id, name, client_id, client_secret, redirect_urls, type, disabled, created_at, updated_at)
    VALUES ('del-test-client', 'Deletion Test Client', 'relayroom-del-test-client',
            NULL, 'urn:ietf:wg:oauth:2.0:oob', 'internal', false, NOW(), NOW())
    ON CONFLICT (client_id) DO NOTHING`
  await rawSql`
    INSERT INTO better_auth_user (id, name, email, email_verified, created_at, updated_at)
    VALUES (${userId}, ${'Owner ' + userId}, ${userId + '@deletion.test'}, true, NOW(), NOW())`
  await rawSql`
    INSERT INTO better_auth_organization (id, name, created_at)
    VALUES (${orgId}, ${'Org ' + orgId}, NOW())`
  await rawSql`
    INSERT INTO better_auth_member (id, organization_id, user_id, role, created_at)
    VALUES (${'del-mem-' + sfx}, ${orgId}, ${userId}, 'member', NOW())`

  const rawToken = <REDACTED>'hex')
  await rawSql`
    INSERT INTO better_auth_oauth_access_token
      (id, access_token, access_token_expires_at, client_id, user_id, scopes, created_at, updated_at)
    VALUES (${'del-tok-' + sfx}, ${rawToken}, ${new Date(Date.now() + 3600_000)},
            'relayroom-del-test-client', ${userId}, 'openid profile', NOW(), NOW())`

  const connectCode = `del-cc-${sfx}`
  const [project] = await db.insert(projects).values({
    organizationId: orgId,
    slug: `del-proj-${sfx}`,
    name: 'Deletion Test Project',
    connectCode,
  }).returning({ id: projects.id })

  const [agent] = await db.insert(agents)
    .values({ projectId: project.id, part, ownerUserId: userId })
    .returning({ id: agents.id })

  return { projectId: project.id, connectCode, userId, rawToken, agentId: agent.id }
}

/** The dashboard's delete: soft delete only. No token revoke, no pager shutdown. */
async function softDelete(agentId: string): Promise<void> {
  await db.update(agents).set({ deletedAt: new Date() }).where(eq(agents.id, agentId))
}

async function isLive(agentId: string): Promise<boolean> {
  const [row] = await db.select({ id: agents.id }).from(agents)
    .where(and(eq(agents.id, agentId), isNull(agents.deletedAt)))
  return !!row
}

describe('a soft-deleted part is not revived by its own traffic', () => {
  it('heartbeat is rejected and leaves the part deleted', async () => {
    const f = await fixture('ghost-hb')
    await softDelete(f.agentId)

    const res = await app.request(`/mcp/${f.connectCode}/heartbeat`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ part: 'ghost-hb' }),
    })

    expect(res.status).toBe(404)
    expect(await isLive(f.agentId)).toBe(false)
  })

  it('a repeating pager cannot wear the deletion down', async () => {
    const f = await fixture('ghost-loop')
    await softDelete(f.agentId)

    for (let i = 0; i < 5; i++) {
      await app.request(`/mcp/${f.connectCode}/heartbeat`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ part: 'ghost-loop' }),
      })
    }

    expect(await isLive(f.agentId)).toBe(false)
  })

  it('usage ingest is rejected and leaves the part deleted', async () => {
    const f = await fixture('ghost-usage')
    await softDelete(f.agentId)

    const res = await app.request(`/mcp/${f.connectCode}/usage`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ part: 'ghost-usage', usage: { input_tokens: <REDACTED> output_tokens: <REDACTED> } }),
    })

    expect(res.status).toBe(404)
    expect(await isLive(f.agentId)).toBe(false)
  })

  it('the still-valid token cannot reconnect a deleted part over MCP', async () => {
    const f = await fixture('ghost-mcp')

    // Sanity: the token connects fine while the part is live.
    const before = await app.request(`/mcp/${f.connectCode}?part=ghost-mcp`, {
      method: 'POST',
      headers: {
        'authorization': `Bearer ${f.rawToken}`,
        'content-type': 'application/json',
        'accept': 'application/json, text/event-stream',
      },
      body: JSON.stringify({
        jsonrpc: '2.0', id: 1, method: 'initialize',
        params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 't', version: '1' } },
      }),
    })
    expect(before.status).toBe(200)

    // Deleting the part does NOT revoke the token, so the same call must now fail.
    await softDelete(f.agentId)
    const after = await app.request(`/mcp/${f.connectCode}?part=ghost-mcp`, {
      method: 'POST',
      headers: {
        'authorization': `Bearer ${f.rawToken}`,
        'content-type': 'application/json',
        'accept': 'application/json, text/event-stream',
      },
      body: JSON.stringify({
        jsonrpc: '2.0', id: 2, method: 'initialize',
        params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 't', version: '1' } },
      }),
    })

    expect(after.status).toBe(404)
    expect(await isLive(f.agentId)).toBe(false)
  })

  it('stays out of the recipient set after a heartbeat attempt', async () => {
    const f = await fixture('ghost-recip')
    await db.insert(agents).values({ projectId: f.projectId, part: 'sender' })
    await softDelete(f.agentId)

    await app.request(`/mcp/${f.connectCode}/heartbeat`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ part: 'ghost-recip' }),
    })

    const recipients = await computeRecipients(db, f.projectId, 'sender', {
      mode: 'send',
      to: ['ghost-recip'],
    })
    expect(recipients.map(r => r.part)).not.toContain('ghost-recip')
  })
})

/**
 * `recall` / `learn` / `recall_used` (FEAT-0001 L0).
 *
 * The guard the whole feature rests on: `learn` always writes a CANDIDATE, and
 * `recall` returns ONLY `trusted`. Everything an agent writes is an unverified
 * claim until a human promotes it, and `recall` is what puts text into another
 * agent's context - so if a candidate could leak through it, an agent could
 * effectively author facts for every other agent. That path is tested from both
 * ends here, and the negative control confirms the tests would notice if it opened.
 */
import { randomBytes } from 'node:crypto'
import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'vitest'
import { and, eq, sql } from 'drizzle-orm'
import { agents, knowledge, projectAccess, projects, recallLogs, threads } from '@relayroom/db'
import { INTERNAL_AGENT_CLIENT_ID, projectScope } from '@relayroom/shared'
import postgres from 'postgres'
import { resetLearnRateLimit } from '../src/routes/mcp'
import { makeTestApp, TEST_DATABASE_URL } from './helpers'

const { app, db, bus } = makeTestApp()
const rawSql = postgres(TEST_DATABASE_URL)

afterAll(async () => {
  await bus.close()
  await db.$client.end()
  await rawSql.end()
})

const SFX = randomBytes(5).toString('hex')
const USER = `kt-user-${SFX}`
const READER = `kt-reader-${SFX}`
const ORG_OWNER = `kt-orgowner-${SFX}`
const ORG = `kt-org-${SFX}`
const CODE = `kt-cc-${SFX}`
const TOKEN = <REDACTED>'hex')
const READER_TOKEN = <REDACTED>'hex')
const ORG_OWNER_TOKEN = <REDACTED>'hex')
let projectId: string

async function seedUser(id: string, orgRole = 'member') {
  await rawSql`
    INSERT INTO better_auth_user (id, name, email, email_verified, created_at, updated_at)
    VALUES (${id}, ${id}, ${id + '@kt.test'}, true, NOW(), NOW())`
  await rawSql`
    INSERT INTO better_auth_member (id, organization_id, user_id, role, created_at)
    VALUES (${'kt-mem-' + randomBytes(4).toString('hex')}, ${ORG}, ${id}, ${orgRole}, NOW())`
}

async function mintToken(raw: string, userId: string) {
  await rawSql`
    INSERT INTO better_auth_oauth_access_token
      (id, access_token, access_token_expires_at, client_id, user_id, scopes, created_at, updated_at)
    VALUES (${'kt-tok-' + randomBytes(6).toString('hex')}, ${raw}, ${new Date(Date.now() + 3600_000)},
            ${INTERNAL_AGENT_CLIENT_ID}, ${userId}, ${projectScope(projectId)}, NOW(), NOW())`
}

beforeAll(async () => {
  await rawSql`
    INSERT INTO better_auth_oauth_application
      (id, name, client_id, client_secret, redirect_urls, type, disabled, created_at, updated_at)
    VALUES ('kt-app', 'Internal', ${INTERNAL_AGENT_CLIENT_ID}, NULL,
            'urn:ietf:wg:oauth:2.0:oob', 'internal', false, NOW(), NOW())
    ON CONFLICT (client_id) DO NOTHING`
  await rawSql`
    INSERT INTO better_auth_organization (id, name, created_at)
    VALUES (${ORG}, 'Knowledge Org', NOW())`
  await seedUser(USER)
  await seedUser(READER)
  // An org owner with NO project_access row: the case the interim gate refused and
  // the shared helper allows, because an org manager administers every project in
  // the org without needing a grant in each one.
  await seedUser(ORG_OWNER, 'owner')

  const [proj] = await db.insert(projects).values({
    organizationId: ORG, slug: `kt-${SFX}`, name: 'Knowledge Project', connectCode: CODE,
  }).returning({ id: projects.id })
  projectId = proj!.id

  await db.insert(agents).values({ projectId, part: 'writer', ownerUserId: USER })
  await db.insert(agents).values({ projectId, part: 'reader', ownerUserId: READER })
  await db.insert(agents).values({ projectId, part: 'orgowner', ownerUserId: ORG_OWNER })
  // The writer has write access; the reader is a member with none granted.
  await db.insert(projectAccess).values({ projectId, userId: USER, level: 'write' })

  await mintToken(TOKEN, USER)
  await mintToken(READER_TOKEN, READER)
  await mintToken(ORG_OWNER_TOKEN, ORG_OWNER)
})

beforeEach(() => {
  resetLearnRateLimit()
})

interface ToolResult { isError: boolean; text: string }

async function callTool(
  part: string, token: <REDACTED> name: string, args: Record<string, unknown>,
): Promise<ToolResult> {
  const res = await app.request(`/mcp/${CODE}?part=${part}`, {
    method: 'POST',
    headers: {
      authorization: `Bearer ${token}`,
      'content-type': 'application/json',
      accept: 'application/json, text/event-stream',
    },
    body: JSON.stringify({
      jsonrpc: '2.0', id: Math.floor(Math.random() * 1e9),
      method: 'tools/call', params: { name, arguments: args },
    }),
  })
  const raw = await res.text()
  const dataLine = raw.split('\n').find(l => l.startsWith('data:'))
  const parsed = JSON.parse(dataLine ? dataLine.slice('data:'.length).trim() : raw)
  const result = parsed.result ?? {}
  return { isError: Boolean(result.isError), text: result.content?.[0]?.text ?? '' }
}

const learn = (args: Record<string, unknown>) => callTool('writer', TOKEN, 'learn', args)
const recall = (args: Record<string, unknown>, part = 'reader', token = <REDACTED> =>
  callTool(part, token, 'recall', args)

/** What a human owner's promotion does to the row. The ledgered transaction that
 *  performs it lives in packages/db and is exercised by its own tests; this is the
 *  state change recall reads. */
async function promote(id: string) {
  await db.update(knowledge)
    .set({ validationState: 'trusted', promotedAt: new Date(), confidence: 0.8 })
    .where(eq(knowledge.id, id))
}

describe('learn', () => {
  it('records a candidate and says so', async () => {
    const r = await learn({
      title: 'Postgres NOTIFY payloads cap at 8000 bytes',
      body: 'A longer payload throws; the bus falls back to local delivery.',
      kind: 'pitfall',
    })
    expect(r.isError).toBe(false)
    expect(JSON.parse(r.text)).toMatchObject({ validationState: 'candidate' })

    const { id } = JSON.parse(r.text) as { id: string }
    const [row] = await db.select().from(knowledge).where(eq(knowledge.id, id))
    expect(row!.validationState).toBe('candidate')
    expect(row!.sourceKind).toBe('learn')
    expect(row!.promotedAt).toBeNull()
    expect(row!.confidence).toBe(0)
  })

  it('cannot write a trusted entry by any argument it accepts', async () => {
    // The tool takes no state argument, and there is no branch that sets one.
    // Asserted directly because "an agent cannot promote its own claim" is the
    // premise the rest of the design is built on.
    for (const kind of ['fact', 'convention', 'pitfall', 'decision'] as const) {
      const r = await learn({ title: `t-${kind}`, body: `b-${kind}`, kind })
      expect(JSON.parse(r.text).validationState).toBe('candidate')
    }
    const rows = await db.select({ state: knowledge.validationState })
      .from(knowledge)
      .where(and(eq(knowledge.projectId, projectId), eq(knowledge.sourceKind, 'learn')))
    expect(rows.every(r => r.state === 'candidate')).toBe(true)
  })

  it('accepts an org owner who has no project_access row', async () => {
    // The rule lives in decideProjectAccess, shared with the dashboard, so an org
    // manager is an owner everywhere in the org. This is the behaviour the interim
    // gate did not have, and the reason it was marked as replace-me rather than
    // extend-me.
    const r = await callTool('orgowner', ORG_OWNER_TOKEN, 'learn', {
      title: 'org owners can record lessons', body: 'without a per-project grant', kind: 'fact',
    })
    expect(r.isError).toBe(false)
    expect(JSON.parse(r.text).validationState).toBe('candidate')
  })

  it('refuses a caller without write access', async () => {
    const r = await callTool('reader', READER_TOKEN, 'learn', {
      title: 'x', body: 'y', kind: 'fact',
    })
    expect(r.isError).toBe(true)
    expect(r.text).toMatch(/write access/)
  })

  it('refuses a sourceThreadId from another project', async () => {
    const other = await db.insert(projects).values({
      organizationId: ORG, slug: `kt-other-${SFX}`, name: 'Other', connectCode: `kt-oc-${SFX}`,
    }).returning({ id: projects.id })
    const [t] = await db.insert(threads)
      .values({ projectId: other[0]!.id, subject: 'elsewhere' }).returning({ id: threads.id })

    const r = await learn({ title: 'x', body: 'y', kind: 'fact', sourceThreadId: t!.id })
    expect(r.isError).toBe(true)
    expect(r.text).toMatch(/not in your project/)
  })

  it('rejects loudly at the rate limit instead of dropping the entry', async () => {
    // An agent that believes it recorded something and did not is worse off than
    // one that was told. The error must say nothing was written.
    let refusal: ToolResult | null = null
    for (let i = 0; i < 25; i++) {
      const r = await learn({ title: `bulk ${i}`, body: `body ${i}`, kind: 'fact' })
      if (r.isError) { refusal = r; break }
    }
    expect(refusal).not.toBeNull()
    expect(refusal!.text).toMatch(/rate limit/)
    expect(refusal!.text).toMatch(/NOTHING was recorded/)
  })

  it('redacts a matched span from title and body before storing (learn path)', async () => {
    // The learn path is not exempt from the denylist - a human can paste a secret.
    // Set a project denylist, then confirm the stored candidate has the span dropped.
    await db.update(projects)
      // A literal rule, not a regex: the operator can no longer author one, so the
      // test configures what the product can actually store.
      .set({ knowledgeConfig: { redactionRules: [{ kind: 'literal', value: 'sk-deadbeef' }] } })
      .where(eq(projects.id, projectId))
    try {
      const r = await learn({
        title: 'rotate sk-deadbeef now', body: 'the key sk-deadbeef must be rotated', kind: 'pitfall',
      })
      expect(r.isError).toBe(false)
      const { id } = JSON.parse(r.text) as { id: string }
      const [row] = await db.select().from(knowledge).where(eq(knowledge.id, id))
      expect(row!.title).not.toContain('sk-deadbeef')
      expect(row!.body).not.toContain('sk-deadbeef')
      expect(row!.body).toContain('must be rotated')
    }
    finally {
      await db.update(projects).set({ knowledgeConfig: {} }).where(eq(projects.id, projectId))
    }
  })

  it('rejects a learn whose body redacts away to nothing', async () => {
    await db.update(projects)
      .set({ knowledgeConfig: { redactionRules: [{ kind: 'literal', value: 'sk-onlysecret' }] } })
      .where(eq(projects.id, projectId))
    try {
      const r = await learn({ title: 't', body: 'sk-onlysecret', kind: 'fact' })
      expect(r.isError).toBe(true)
      expect(r.text).toMatch(/empty after redaction/)
    }
    finally {
      await db.update(projects).set({ knowledgeConfig: {} }).where(eq(projects.id, projectId))
    }
  })
})

describe('recall', () => {
  it('does NOT return a candidate', async () => {
    const created = await learn({
      title: 'kryptonite handling procedure',
      body: 'kryptonite must be stored in a lead-lined container',
      kind: 'convention',
    })
    const { id } = JSON.parse(created.text) as { id: string }

    const r = await recall({ query: 'kryptonite handling' })
    expect(r.isError).toBe(false)
    const { entries } = JSON.parse(r.text) as { entries: { id: string }[] }
    expect(entries.map(e => e.id)).not.toContain(id)
  })

  it('returns it once a human promotes it - the whole loop', async () => {
    const created = await learn({
      title: 'deploy window is Tuesday morning',
      body: 'releases go out Tuesday before noon so someone is around if it breaks',
      kind: 'convention',
    })
    const { id } = JSON.parse(created.text) as { id: string }

    expect(JSON.parse((await recall({ query: 'deploy window' })).text).entries).toHaveLength(0)
    await promote(id)

    // A DIFFERENT agent recalls it: the point is that a lesson crosses agents.
    const r = await recall({ query: 'deploy window' })
    const { entries, queryId } = JSON.parse(r.text) as {
      entries: { id: string; kind: string; title: string; confidence: number; sourceRefs: unknown[] }[]
      queryId: string
    }
    expect(entries.map(e => e.id)).toContain(id)
    const hit = entries.find(e => e.id === id)!
    expect(hit.kind).toBe('convention')
    expect(hit.confidence).toBeCloseTo(0.8)
    expect(Array.isArray(hit.sourceRefs)).toBe(true)
    expect(queryId).toMatch(/^[0-9a-f-]{36}$/)
  })

  it('filters by kind', async () => {
    const a = JSON.parse((await learn({
      title: 'zeppelin inflation checklist', body: 'check the seams first', kind: 'convention',
    })).text) as { id: string }
    const b = JSON.parse((await learn({
      title: 'zeppelin inflation incident', body: 'the seams failed in 1937', kind: 'pitfall',
    })).text) as { id: string }
    await promote(a.id); await promote(b.id)

    const r = await recall({ query: 'zeppelin inflation', kind: 'pitfall' })
    const ids = (JSON.parse(r.text) as { entries: { id: string }[] }).entries.map(e => e.id)
    expect(ids).toContain(b.id)
    expect(ids).not.toContain(a.id)
  })

  it('omits an expired entry', async () => {
    const created = JSON.parse((await learn({
      title: 'temporary embargo on widget shipments', body: 'do not ship widgets', kind: 'fact',
    })).text) as { id: string }
    await promote(created.id)
    await db.update(knowledge)
      .set({ expiresAt: new Date(Date.now() - 60_000) })
      .where(eq(knowledge.id, created.id))

    const r = await recall({ query: 'widget shipments embargo' })
    expect((JSON.parse(r.text) as { entries: unknown[] }).entries).toHaveLength(0)
  })

  it('does not reach another project\'s knowledge', async () => {
    const [other] = await db.insert(projects).values({
      organizationId: ORG, slug: `kt-x-${SFX}`, name: 'X', connectCode: `kt-xc-${SFX}`,
    }).returning({ id: projects.id })
    await db.insert(knowledge).values({
      projectId: other!.id, kind: 'fact', title: 'flux capacitor calibration',
      body: 'calibrate the flux capacitor quarterly', sourceKind: 'human',
      validationState: 'trusted', confidence: 1,
    })

    const r = await recall({ query: 'flux capacitor calibration' })
    expect((JSON.parse(r.text) as { entries: unknown[] }).entries).toHaveLength(0)
  })

  it('logs the query as a hash, never the text', async () => {
    const secret = '<REDACTED> with customer acme corp'
    const r = await recall({ query: secret })
    const { queryId } = JSON.parse(r.text) as { queryId: string }

    const [log] = await db.select().from(recallLogs).where(eq(recallLogs.id, queryId))
    expect(log!.projectId).toBe(projectId)
    expect(log!.queryHash).toMatch(/^[0-9a-f]{64}$/)
    expect(log!.queryHash).not.toContain('acme')
    // Same query, same hash - that grouping is what a hit rate is computed over.
    const again = JSON.parse((await recall({ query: `  ${secret.toUpperCase()}  ` })).text) as { queryId: string }
    const [log2] = await db.select().from(recallLogs).where(eq(recallLogs.id, again.queryId))
    expect(log2!.queryHash).toBe(log!.queryHash)
  })

  it('is available to a member with no access level granted', async () => {
    // recall requires only a non-banned member; resolveConnection already proved
    // that, which is why the tool adds no check of its own.
    const created = JSON.parse((await learn({
      title: 'lighthouse keeper rotation', body: 'rotates every six weeks', kind: 'fact',
    })).text) as { id: string }
    await promote(created.id)

    const r = await recall({ query: 'lighthouse keeper' }, 'reader', READER_TOKEN)
    expect(r.isError).toBe(false)
    expect((JSON.parse(r.text) as { entries: { id: string }[] }).entries.map(e => e.id))
      .toContain(created.id)
  })
})

describe('recall_used', () => {
  it('records the entry that was acted on', async () => {
    const created = JSON.parse((await learn({
      title: 'barometer readings drift in humidity', body: 'recalibrate above 80% humidity', kind: 'pitfall',
    })).text) as { id: string }
    await promote(created.id)

    const { queryId } = JSON.parse((await recall({ query: 'barometer humidity' })).text) as { queryId: string }
    const r = await callTool('reader', READER_TOKEN, 'recall_used', { queryId, knowledgeId: created.id })
    expect(r.isError).toBe(false)
    expect(JSON.parse(r.text)).toEqual({ ok: true })

    const [log] = await db.select().from(recallLogs).where(eq(recallLogs.id, queryId))
    expect(log!.usedKnowledgeId).toBe(created.id)
  })

  it('refuses an entry that query never returned', async () => {
    // Otherwise an agent could name any id and inflate the hit rate.
    const unrelated = JSON.parse((await learn({
      title: 'unrelated entry', body: 'not returned by the query below', kind: 'fact',
    })).text) as { id: string }
    const { queryId } = JSON.parse((await recall({ query: 'something else entirely' })).text) as { queryId: string }

    const r = await callTool('reader', READER_TOKEN, 'recall_used', {
      queryId, knowledgeId: unrelated.id,
    })
    expect(r.isError).toBe(true)
    expect(r.text).toMatch(/not among the results/)
  })

  it('refuses a queryId from another project', async () => {
    const [other] = await db.insert(projects).values({
      organizationId: ORG, slug: `kt-y-${SFX}`, name: 'Y', connectCode: `kt-yc-${SFX}`,
    }).returning({ id: projects.id })
    const [foreign] = await db.insert(recallLogs)
      .values({ projectId: other!.id, returnedKnowledgeIds: [] })
      .returning({ id: recallLogs.id })

    const r = await callTool('reader', READER_TOKEN, 'recall_used', {
      queryId: foreign!.id, knowledgeId: foreign!.id,
    })
    expect(r.isError).toBe(true)
    expect(r.text).toMatch(/unknown queryId/)
  })
})

/**
 * Bearer enforcement on the connect-code endpoints (SRV-H2).
 *
 * The connect code is project-wide, travels in the URL path, never expires, and a
 * ban cannot take it away - banProjectMember deletes the member's tokens, which
 * shut the MCP path immediately while these endpoints kept answering. `part` was
 * an unauthenticated claim on top of that, so a code-holder could name any part
 * and read its unread subjects.
 *
 * Now the token is authoritative for (user, project) and `part` is checked against
 * it. The token cannot IDENTIFY a part - one token can hold agent_connection rows
 * for several parts - so the request still names one and the caller must own it.
 *
 * Two enforcement levels, by whether an un-upgraded client would fail LOUDLY:
 *   required - /wake/claim, /wake/delivered, /pending-wake. The pager and the
 *              channel already send the header, and a pager that cannot claim a
 *              lease stops nudging where someone will notice.
 *   grace    - /heartbeat, /usage, /role, /relayroom-md, /unread. Each of these
 *              fails silently in a client that has not been upgraded: the
 *              ask-guard fails open, the usage hook swallows its errors, and the
 *              tmux status bar's inbox counter keeps displaying its last value.
 */
import { randomBytes } from 'node:crypto'
import { afterAll, beforeAll, describe, expect, it } from 'vitest'
import { eq } from 'drizzle-orm'
import { agents, projectAccess, projects } from '@relayroom/db'
import postgres from 'postgres'
import { makeTestApp, TEST_DATABASE_URL } from './helpers'

const { app, db, bus } = makeTestApp()
const rawSql = postgres(TEST_DATABASE_URL)

afterAll(async () => {
  await bus.close()
  await db.$client.end()
  await rawSql.end()
})

const CLIENT_ID = 'relayroom-runtime-auth-client'

beforeAll(async () => {
  await rawSql`
    INSERT INTO better_auth_oauth_application
      (id, name, client_id, client_secret, redirect_urls, type, disabled, created_at, updated_at)
    VALUES ('runtime-auth-client', 'Runtime Auth Test Client', ${CLIENT_ID},
            NULL, 'urn:ietf:wg:oauth:2.0:oob', 'internal', false, NOW(), NOW())
    ON CONFLICT (client_id) DO NOTHING`
})

async function makeUser(orgId: string, sfx: string): Promise<{ userId: string; token: <REDACTED> }> {
  const userId = `ra-user-${sfx}`
  await rawSql`
    INSERT INTO better_auth_user (id, name, email, email_verified, created_at, updated_at)
    VALUES (${userId}, ${'User ' + userId}, ${userId + '@runtime.test'}, true, NOW(), NOW())`
  await rawSql`
    INSERT INTO better_auth_member (id, organization_id, user_id, role, created_at)
    VALUES (${'ra-mem-' + sfx}, ${orgId}, ${userId}, 'member', NOW())`
  const token = <REDACTED>'hex')
  await rawSql`
    INSERT INTO better_auth_oauth_access_token
      (id, access_token, access_token_expires_at, client_id, user_id, scopes, created_at, updated_at)
    VALUES (${'ra-tok-' + sfx}, ${token}, ${new Date(Date.now() + 3600_000)},
            ${CLIENT_ID}, ${userId}, 'openid profile', NOW(), NOW())`
  return { userId, token }
}

interface Scene {
  projectId: string
  connectCode: string
  orgId: string
  owner: { userId: string; token: <REDACTED> }
  agentId: string
}

/** A project with one part owned by `owner`. */
async function scene(part = 'worker'): Promise<Scene> {
  const sfx = randomBytes(6).toString('hex')
  const orgId = `ra-org-${sfx}`
  await rawSql`
    INSERT INTO better_auth_organization (id, name, created_at)
    VALUES (${orgId}, ${'Org ' + orgId}, NOW())`

  const owner = await makeUser(orgId, sfx)
  const connectCode = `ra-cc-${sfx}`
  const [project] = await db.insert(projects).values({
    organizationId: orgId, slug: `ra-proj-${sfx}`, name: 'Runtime Auth Project', connectCode,
  }).returning({ id: projects.id })

  const [agent] = await db.insert(agents)
    .values({ projectId: project!.id, part, ownerUserId: owner.userId })
    .returning({ id: agents.id })

  return { projectId: project!.id, connectCode, orgId, owner, agentId: agent!.id }
}

const bearer = (t: string) => ({ Authorization: `Bearer ${t}` })

describe('bearer required (wake delivery)', () => {
  it('/wake/claim refuses a request with no bearer token, with a challenge header', async () => {
    const s = await scene()
    const res = await app.request(`/mcp/${s.connectCode}/wake/claim`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ part: 'worker', holder: 'h1' }),
    })
    expect(res.status).toBe(401)
    expect(res.headers.get('WWW-Authenticate')).toMatch(/Bearer/)
  })

  it('/wake/claim and /pending-wake refuse a request with no bearer token', async () => {
    const s = await scene()
    const claim = await app.request(`/mcp/${s.connectCode}/wake/claim`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ part: 'worker', holder: 'h1' }),
    })
    expect(claim.status).toBe(401)

    const pending = await app.request(`/mcp/${s.connectCode}/pending-wake?part=worker&holder=h1`)
    expect(pending.status).toBe(401)
  })

  it('/wake/claim still works for the owning pager', async () => {
    const s = await scene()
    const res = await app.request(`/mcp/${s.connectCode}/wake/claim`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', ...bearer(s.owner.token) },
      body: JSON.stringify({ part: 'worker', holder: 'h1' }),
    })
    // No active wake to lease, but it got past authorization - that is the point.
    expect(res.status).toBe(200)
    expect((await res.json()) as { noWake?: boolean }).toMatchObject({ noWake: true })
  })
})

describe('grace period (clients that fail silently)', () => {
  it('/unread still answers the tmux status bar, which sends no token', async () => {
    // The inbox counter in the status bar is a curl line in the generated rr.sh
    // (packages/cli/src/init.ts). It has no Authorization header yet, and on a
    // failed fetch it keeps displaying its last value - so rejecting it here would
    // freeze the number rather than show anyone an error.
    const s = await scene()
    const res = await app.request(`/mcp/${s.connectCode}/unread?part=worker`)
    expect(res.status).toBe(200)
  })


  it('/heartbeat still accepts a client that sends no bearer token', async () => {
    const s = await scene()
    const res = await app.request(`/mcp/${s.connectCode}/heartbeat`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ part: 'worker' }),
    })
    expect(res.status).toBe(200)
  })

  it('/heartbeat accepts the owner when the token IS sent', async () => {
    const s = await scene()
    const res = await app.request(`/mcp/${s.connectCode}/heartbeat`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', ...bearer(s.owner.token) },
      body: JSON.stringify({ part: 'worker' }),
    })
    expect(res.status).toBe(200)
  })

  it('a BAD token is rejected rather than falling back to the legacy path', async () => {
    // The grace period is for clients that send nothing yet. A token that is present
    // but expired or revoked must fail: silently downgrading it to weaker auth would
    // undo the expiry it is being checked for.
    const s = await scene()
    const res = await app.request(`/mcp/${s.connectCode}/heartbeat`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', ...bearer('not-a-real-token') },
      body: JSON.stringify({ part: 'worker' }),
    })
    expect(res.status).toBe(401)
  })

  it('a banned member is refused even on a grace endpoint when the token is sent', async () => {
    const s = await scene()
    await db.insert(projectAccess).values({
      projectId: s.projectId, userId: s.owner.userId, level: 'write', bannedAt: new Date(),
    })
    const res = await app.request(`/mcp/${s.connectCode}/heartbeat`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', ...bearer(s.owner.token) },
      body: JSON.stringify({ part: 'worker' }),
    })
    expect(res.status).toBe(403)
  })

  it('/relayroom-md authorizes at project level, with no part', async () => {
    const s = await scene()
    const withToken = <REDACTED> app.request(`/mcp/${s.connectCode}/relayroom-md`, {
      headers: bearer(s.owner.token),
    })
    expect(withToken.status).toBe(200)

    // A member of a DIFFERENT org has no business reading this project's playbook.
    const otherOrg = `ra-org-out-${randomBytes(6).toString('hex')}`
    await rawSql`
      INSERT INTO better_auth_organization (id, name, created_at)
      VALUES (${otherOrg}, 'Outsider Org', NOW())`
    const outsider = await makeUser(otherOrg, randomBytes(6).toString('hex'))
    const res = await app.request(`/mcp/${s.connectCode}/relayroom-md`, {
      headers: bearer(outsider.token),
    })
    expect(res.status).toBe(403)
  })
})

describe('part ownership', () => {
  it('/unread accepts the part owner', async () => {
    const s = await scene()
    const res = await app.request(`/mcp/${s.connectCode}/unread?part=worker`, {
      headers: bearer(s.owner.token),
    })
    expect(res.status).toBe(200)
  })

  it('/unread refuses another member reading a part they do not own', async () => {
    const s = await scene()
    // A second member of the same org: authenticated, in the project, not the owner.
    const other = await makeUser(s.orgId, randomBytes(6).toString('hex'))
    const res = await app.request(`/mcp/${s.connectCode}/unread?part=worker`, {
      headers: bearer(other.token),
    })
    expect(res.status).toBe(403)
  })

  it('/unread refuses a banned member who still holds the connect code', async () => {
    const s = await scene()
    // The ban is what the connect code could not express: the code is project-wide,
    // so it cannot be rotated for one member without cutting off everyone.
    await db.insert(projectAccess).values({
      projectId: s.projectId, userId: s.owner.userId, level: 'write', bannedAt: new Date(),
    })
    const res = await app.request(`/mcp/${s.connectCode}/unread?part=worker`, {
      headers: bearer(s.owner.token),
    })
    expect(res.status).toBe(403)
    expect(((await res.json()) as { error: string }).error).toMatch(/banned/)
  })

  it('a deleted part is refused even for its owner', async () => {
    const s = await scene()
    await db.update(agents).set({ deletedAt: new Date() }).where(eq(agents.id, s.agentId))
    const res = await app.request(`/mcp/${s.connectCode}/unread?part=worker`, {
      headers: bearer(s.owner.token),
    })
    expect(res.status).toBe(404)
  })

  it('an unregistered part is refused', async () => {
    const s = await scene()
    const res = await app.request(`/mcp/${s.connectCode}/unread?part=ghostpart`, {
      headers: bearer(s.owner.token),
    })
    expect(res.status).toBe(404)
  })
})

/**
 * The BUG-0007 backfill (0014) revokes exactly the connections a token was never
 * scoped to - and nothing else.
 *
 * What it must remove is easy. What it must NOT remove is where this goes wrong:
 * standard OAuth tokens are user-scoped by design and carry no project scope at
 * all, so a scope test applied to them revokes every one of their connections.
 * `agent_connection.access_token_id` is nullable and non-unique, so ONE standard
 * token legitimately holding connections in several projects is a real state, and
 * a blanket migration would wipe a working multi-project setup.
 *
 * global-setup has already applied 0014 to this database, so the statement is
 * re-run here against rows seeded per test. It is a plain UPDATE with no ordering
 * dependence, which is what makes that faithful.
 */
import { randomBytes } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { afterAll, beforeAll, describe, expect, it } from 'vitest'
import { eq } from 'drizzle-orm'
import { agentConnections, agents, projects } from '@relayroom/db'
import { INTERNAL_AGENT_CLIENT_ID, projectScope } from '@relayroom/shared'
import postgres from 'postgres'
import { makeTestApp, TEST_DATABASE_URL } from './helpers'

const { db, bus } = makeTestApp()
const rawSql = postgres(TEST_DATABASE_URL)

const MIGRATION = readFileSync(
  fileURLToPath(new URL(
    '../../../packages/db/drizzle/0014_revoke_cross_project_agent_connections.sql',
    import.meta.url,
  )),
  'utf8',
)

afterAll(async () => {
  await bus.close()
  await db.$client.end()
  await rawSql.end()
})

const ORG = `mg-org-${randomBytes(4).toString('hex')}`
const USER = `mg-user-${randomBytes(4).toString('hex')}`
const STANDARD_CLIENT = 'mg-standard-client'

beforeAll(async () => {
  for (const [id, clientId, type] of [
    ['mg-internal-app', INTERNAL_AGENT_CLIENT_ID, 'internal'],
    ['mg-standard-app', STANDARD_CLIENT, 'public'],
  ] as const) {
    await rawSql`
      INSERT INTO better_auth_oauth_application
        (id, name, client_id, client_secret, redirect_urls, type, disabled, created_at, updated_at)
      VALUES (${id}, ${'App ' + id}, ${clientId}, NULL,
              'urn:ietf:wg:oauth:2.0:oob', ${type}, false, NOW(), NOW())
      ON CONFLICT (client_id) DO NOTHING`
  }
  await rawSql`
    INSERT INTO better_auth_user (id, name, email, email_verified, created_at, updated_at)
    VALUES (${USER}, 'Migration User', ${USER + '@mg.test'}, true, NOW(), NOW())`
  await rawSql`
    INSERT INTO better_auth_organization (id, name, created_at)
    VALUES (${ORG}, 'Migration Org', NOW())`
})

async function project(): Promise<{ id: string; agentId: string }> {
  const sfx = randomBytes(6).toString('hex')
  const [p] = await db.insert(projects).values({
    organizationId: ORG, slug: `mg-${sfx}`, name: 'Migration Project', connectCode: `mg-cc-${sfx}`,
  }).returning({ id: projects.id })
  const [a] = await db.insert(agents)
    .values({ projectId: p!.id, part: 'worker' }).returning({ id: agents.id })
  return { id: p!.id, agentId: a!.id }
}

async function mintToken(clientId: string, scopes: string | null): Promise<string> {
  const id = `mg-tok-${randomBytes(8).toString('hex')}`
  await rawSql`
    INSERT INTO better_auth_oauth_access_token
      (id, access_token, access_token_expires_at, client_id, user_id, scopes, created_at, updated_at)
    VALUES (${id}, ${randomBytes(24).toString('hex')}, ${new Date(Date.now() + 3600_000)},
            ${clientId}, ${USER}, ${scopes}, NOW(), NOW())`
  return id
}

async function connection(agentId: string, tokenId: <REDACTED> | null): Promise<string> {
  const [row] = await db.insert(agentConnections)
    .values({ agentId, accessTokenId: <REDACTED> status: 'connected', connectedAt: new Date() })
    .returning({ id: agentConnections.id })
  return row!.id
}

async function statusOf(connectionId: string): Promise<string> {
  const [row] = await db.select({ status: agentConnections.status })
    .from(agentConnections).where(eq(agentConnections.id, connectionId))
  return row!.status
}

const runMigration = () => rawSql.unsafe(MIGRATION)

describe('0014 revokes cross-project internal connections', () => {
  it('revokes an internal connection outside the token scope', async () => {
    const a = await project()
    const b = await project()
    const tok = await mintToken(INTERNAL_AGENT_CLIENT_ID, projectScope(a.id))
    const stray = await connection(b.agentId, tok)

    await runMigration()
    expect(await statusOf(stray)).toBe('revoked')
  })

  it('keeps the internal connection the token IS scoped to', async () => {
    const a = await project()
    const tok = await mintToken(INTERNAL_AGENT_CLIENT_ID, projectScope(a.id))
    const good = await connection(a.agentId, tok)

    await runMigration()
    expect(await statusOf(good)).toBe('connected')
  })

  it('revokes an internal connection whose token has no usable scope', async () => {
    for (const scopes of [null, '', '   ']) {
      const a = await project()
      const tok = await mintToken(INTERNAL_AGENT_CLIENT_ID, scopes)
      const conn = await connection(a.agentId, tok)

      await runMigration()
      expect(await statusOf(conn)).toBe('revoked')
    }
  })

  it('does not match a project id by prefix', async () => {
    // 'project:<id>' as a substring of a longer scope element must not count.
    const a = await project()
    const tok = await mintToken(INTERNAL_AGENT_CLIENT_ID, `${projectScope(a.id)}-extra`)
    const conn = await connection(a.agentId, tok)

    await runMigration()
    expect(await statusOf(conn)).toBe('revoked')
  })
})

describe('0014 preserves everything else', () => {
  it('keeps a standard OAuth connection that carries no project scope', async () => {
    const a = await project()
    const tok = await mintToken(STANDARD_CLIENT, 'openid profile')
    const conn = await connection(a.agentId, tok)

    await runMigration()
    expect(await statusOf(conn)).toBe('connected')
  })

  it('keeps ALL of a standard OAuth token\'s connections across several projects', async () => {
    // The case review 2 caught: access_token_id is nullable and non-unique, so this
    // is a legitimate state, and a scope test applied to a user-scoped token would
    // revoke every one of these.
    const tok = await mintToken(STANDARD_CLIENT, 'openid profile offline_access')
    const conns: string[] = []
    for (let i = 0; i < 3; i++) {
      const p = await project()
      conns.push(await connection(p.agentId, tok))
    }

    await runMigration()
    for (const c of conns) expect(await statusOf(c)).toBe('connected')
  })

  it('keeps a standard OAuth connection even with a null scope', async () => {
    const a = await project()
    const tok = await mintToken(STANDARD_CLIENT, null)
    const conn = await connection(a.agentId, tok)

    await runMigration()
    expect(await statusOf(conn)).toBe('connected')
  })

  it('keeps a connection with no token at all', async () => {
    const a = await project()
    const conn = await connection(a.agentId, null)

    await runMigration()
    expect(await statusOf(conn)).toBe('connected')
  })

  it('is idempotent and leaves an already-revoked row alone', async () => {
    const a = await project()
    const b = await project()
    const tok = await mintToken(INTERNAL_AGENT_CLIENT_ID, projectScope(a.id))
    const good = await connection(a.agentId, tok)
    const stray = await connection(b.agentId, tok)

    await runMigration()
    await runMigration()
    expect(await statusOf(stray)).toBe('revoked')
    expect(await statusOf(good)).toBe('connected')
  })
})

describe('0014 and a refreshed token', () => {
  it('follows the refreshed row, because a refresh copies client_id and scopes', async () => {
    // better-auth writes a new access_token row on refresh, carrying the original
    // client_id and scopes forward. The migration therefore judges the refreshed
    // row on the same scope the original had - asserted against stored columns
    // rather than a hand-built fixture, so a change in what refresh carries shows up
    // here instead of passing silently.
    const a = await project()
    const b = await project()
    const original = await mintToken(INTERNAL_AGENT_CLIENT_ID, projectScope(a.id))

    const [row] = await rawSql`
      SELECT client_id, scopes FROM better_auth_oauth_access_token WHERE id = ${original}`
    expect(row!.client_id).toBe(INTERNAL_AGENT_CLIENT_ID)
    expect(row!.scopes).toBe(projectScope(a.id))

    // A refresh: same client_id and scopes, new token row.
    const refreshed = await mintToken(row!.client_id as string, row!.scopes as string)
    const good = await connection(a.agentId, refreshed)
    const stray = await connection(b.agentId, refreshed)

    await runMigration()
    expect(await statusOf(good)).toBe('connected')
    expect(await statusOf(stray)).toBe('revoked')
  })
})

/**
 * The MCP tool contract, snapshotted.
 *
 * `tools/list` is what every agent reads to decide what it can do and how to call
 * it, so a change here changes behaviour for every connected agent at once - and
 * nothing was pinning it. Renaming an argument, dropping an enum value, or
 * loosening a description all shipped silently.
 *
 * The snapshot is taken from the NORMALIZED reply, after cleanJsonSchema has
 * stripped the draft-07 keywords strict clients reject. That is the shape clients
 * actually receive; snapshotting the raw SDK output would pin something no client
 * sees.
 *
 * Written before the 0.5.0 knowledge tools exist on purpose: it fixes the current
 * contract first, so adding recall/learn/recall_used shows up as a diff a reviewer
 * can read rather than arriving inside a baseline nobody had checked.
 */
