  agentPart: string | null
  /** "main" shows the crown. */
  agentRole?: string | null
  ownerName?: string | null
  className?: string
}

/**
 * Compact "who wrote this" marker: agent part (links to the agent detail), a
 * crown when it is the project main agent, and the owner name. Used in thread /
 * event lists and the overview cards so rows show which agent (and whose) acted.
 *
 * When placed inside a row that itself is a stretched link, pass a `relative
 * z-10` className so this link stays clickable above the row overlay.
 */
export function AgentAuthor({
  projectSlug,
  agentId,
  agentPart,
  agentRole,
  ownerName,
  className,
}: Props) {
  if (!agentPart) return null
  const isMain = agentRole === "main"

  const inner = (
    <span className="inline-flex items-center gap-1 font-mono font-medium text-foreground/80">
      {isMain && <CrownIcon className="h-3 w-3 shrink-0 text-amber-500" />}
      {agentPart}
    </span>
  )

  return (
    <span className={cn("inline-flex min-w-0 items-center gap-1.5 text-xs text-muted-foreground", className)}>
      {agentId ? (
        <Link
          href={`/projects/${projectSlug}/agents/${agentId}`}
          className="inline-flex items-center gap-1 truncate hover:underline"
        >
          {inner}
        </Link>
      ) : (
        inner
      )}
      {ownerName && (
        <>
          <span aria-hidden className="text-muted-foreground/60">·</span>
          <span className="truncate">{ownerName}</span>
        </>
      )}
    </span>
  )
}

"use client"

import { useEffect, useRef, useState } from "react"
import { usePathname, useRouter, useSearchParams } from "next/navigation"
import { useTranslations } from "next-intl"
import { toast } from "sonner"
import { CopyIcon, CheckIcon, InfoIcon, PlugZapIcon } from "lucide-react"
import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog"
import { cn } from "@/lib/utils"
import { Checkbox } from "@/components/ui/checkbox"
import { connectAgent } from "@/modules/agent/actions"
import { useRealtime } from "@/components/realtime/realtime-provider"

type AgentId = "claude" | "codex"
// Selectable CLIs in the connect guide.
//
// `agy` (Antigravity) is deliberately NOT offered here any more, and this is a
// change to the GUIDE only: the CLI still accepts `--agent agy`, rr.sh still
// launches it and the hooks path is intact, so worktrees already set up that way
// keep working. Removing it from the type as well is the point - a selectable id
// with no branch to build its command is a dead path that compiles.
const AGENTS: { id: AgentId; label: string }[] = [
  { id: "claude", label: "Claude Code" },
  { id: "codex", label: "Codex" },
]

// How to invoke the RelayRoom CLI. Defaults to `npx -y @relayroom/cli` (works for
// anyone once published - npx auto-fetches it). For local dev before publish, set
// NEXT_PUBLIC_RELAYROOM_CLI=relayroom (the `npm link`ed global bin), since npx
// can't resolve an unpublished scoped package and 404s.
const CLI_CMD = process.env.NEXT_PUBLIC_RELAYROOM_CLI ?? "npx -y @relayroom/cli"

// The token authenticates every MCP call. Bake it into the command so the agent
// authenticates directly (no OAuth/IDE prompt): claude takes an inline header;
// codex reads it from an env var (the `export` line above the add). We remove any
// existing entry first so a re-connect swaps in the fresh token instead of hitting
// "already exists" and keeping a stale (failing) config.
//
// The `agy` branch that used to live here merged a server into
// ~/.gemini/config/mcp_config.json by hand, because Antigravity has no `mcp add`.
// It went with the option: the guide cannot offer agy any more, so the branch was
// unreachable, and an unreachable copy of a config-file writer is the kind that
// drifts from the CLI's own AGY_MCP_MERGE_SCRIPT without anyone noticing. That
// script in packages/cli/src/providers.ts is the surviving one.
function mcpAddCommand(agent: AgentId, name: string, url: string, token: <REDACTED> string {
  const bin = agent === "codex" ? "codex" : "claude"
  const add =
    agent === "codex"
      ? `${bin} mcp add ${name} --url "${url}" --bearer-token-env-var RELAYROOM_TOKEN`
      : `${bin} mcp add --transport http ${name} "${url}" --header "Authorization: Bearer ${token}"`
  return `${bin} mcp remove ${name} 2>/dev/null; ${add}`
}

// Each CLI's "skip all approval prompts" launch flag. On by default here, because
// RelayRoom's model is an agent in a tmux session nobody is watching: an agent that
// stops at an approval prompt hangs there forever, and the human never sees it ask.
// The flag still bypasses ALL permission checks, not just RelayRoom's - that does not
// stop being true because it is the default, and the toggle copy says so.
function bypassFlag(agent: AgentId): string {
  return agent === "codex"
    ? "--dangerously-bypass-approvals-and-sandbox"
    : "--dangerously-skip-permissions"
}

interface Props {
  connectCode: string
  /** The agent part to connect a local coding tool to. */
  part: string
  /** Project slug - makes the tmux session name unique across projects, so two
   * projects can both have a "main" agent without a `tmux new -s main` collision. */
  projectSlug: string
  serverBase?: string
  triggerLabel?: string
  /** Open on mount (e.g. right after registration, via ?connect=1). */
  defaultOpen?: boolean
}

/**
 * Shows how to connect a local coding tool (Claude Code / Codex / Antigravity) to an
 * already-registered agent - one job. Issues a fresh auth token when opened and
 * renders the copy-paste setup commands. Separate from the register dialog.
 */
export function AgentConnectGuideDialog({ connectCode, part, projectSlug, serverBase, triggerLabel, defaultOpen }: Props) {
  const base = serverBase ?? process.env.NEXT_PUBLIC_RELAYROOM_SERVER_BASE ?? "http://localhost:48801"
  const t = useTranslations("project")
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const [open, setOpen] = useState(defaultOpen ?? false)
  // CLIs to connect. Single-select by default; the multi checkbox opts into
  // picking several (advanced rotation setup, see the note when >1).
  const [selected, setSelected] = useState<AgentId[]>(["claude"])
  const [multiMode, setMultiMode] = useState(false)
  // Append each CLI's "skip approval prompts" launch flag to the foreground launch
  // line. ON by default: these agents run unattended, so a permission prompt is not
  // a question anyone answers - it is where the agent stops. Unchecking restores
  // every permission check, at the cost of an agent that waits for a human.
  const [bypassMode, setBypassMode] = useState(true)
  // Which multiplexer the generated command should set up. INTENT, not state: this is
  // what the reader is about to ask for, and it is never rendered as what the part is
  // actually delivering through - a worktree can ask for herdr and get tmux, and the
  // part card sources that from what the pager reports rather than from here.
  //
  // Defaults to tmux because tmux is the assumption that is right without the reader
  // having installed anything.
  const [multiplexer, setMultiplexer] = useState<"tmux" | "herdr">("tmux")
  const [token, setToken] = useState<string | null>(null)
  // Guard so the token is issued exactly once per open - NOT a cancellable
  // effect, because router.replace (stripping ?connect) re-renders mid-request
  // and a cancel flag would drop the result, leaving the dialog stuck loading.
  const issuingRef = useRef(false)

  useEffect(() => {
    if (!open || token || issuingRef.current) return
    issuingRef.current = true
    connectAgent({ connectCode, part, nickname: "" })
      .then((res) => {
        if (res.result) setToken(res.item.token)
        else {
          issuingRef.current = false
          toast.error(res.message ?? t("agentConnect.toastError"))
        }
      })
      .catch(() => {
        issuingRef.current = false
        toast.error(t("agentConnect.toastError"))
      })
  }, [open, token, connectCode, part, t])

  // Auto-opened via ?connect=1: strip ONLY the connect param (keep any other query),
  // so a refresh won't reopen/reissue but unrelated params survive.
  useEffect(() => {
    if (defaultOpen) {
      const params = new URLSearchParams(searchParams.toString())
      params.delete("connect")
      const qs = params.toString()
      router.replace(qs ? `${pathname}?${qs}` : pathname)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // When the agent's pager first beats (it connected), confirm + close the dialog.
  // The pager event arrives over the project SSE stream; guard so we fire once.
  const realtime = useRealtime()
  const confirmedRef = useRef(false)
  useEffect(() => {
    if (!open || !realtime) return
    return realtime.onAgentConnected(part, () => {
      if (confirmedRef.current) return
      confirmedRef.current = true
      toast.success(t("agentConnectGuide.toastConnected", { part }))
      setOpen(false)
      router.refresh()
    })
  }, [open, realtime, part, t, router])

  // Reset per-open state when the dialog CLOSES, so a reopen issues a FRESH token and
  // the connect-confirmation can fire again. Without this, a reopened dialog reuses a
  // stale token (the issue-once guard sees the old one) and the once-guard swallows
  // the pager-connected event forever.
  useEffect(() => {
    if (!open) {
      setToken(null)
      issuingRef.current = false
      confirmedRef.current = false
    }
  }, [open])

  // Toggle a CLI in/out of the selection, keeping canonical (AGENTS) order and
  // never letting the selection drop to empty.
  const toggleAgent = (id: AgentId) =>
    setSelected((prev) =>
      prev.includes(id)
        ? prev.length > 1
          ? prev.filter((x) => x !== id)
          : prev
        : AGENTS.filter((a) => a.id === id || prev.includes(a.id)).map((a) => a.id),
    )

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger render={<Button size="sm" variant="outline" />}>
        <PlugZapIcon className="mr-1.5 size-[16px]" />
        {triggerLabel ?? t("agentConnectGuide.triggerLabel")}
      </DialogTrigger>

      <DialogContent className="sm:max-w-xl lg:max-w-2xl max-h-[85vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{t("agentConnectGuide.dialogTitle")}</DialogTitle>
          <DialogDescription>
            {t.rich("agentConnectGuide.dialogDescription", { part: () => <strong className="font-mono">{part}</strong> })}
          </DialogDescription>
        </DialogHeader>

        {!token ? (
          <div className="flex items-center justify-center gap-2 py-10 text-sm text-muted-foreground">
            <span className="h-4 w-4 animate-spin rounded-full border-2 border-muted-foreground/30 border-t-foreground" />
            {t("agentConnectGuide.preparing")}
          </div>
        ) : (
          <div className="space-y-4">
            <div className="space-y-2">
              <p className="text-xs text-muted-foreground">{t("agentConnectGuide.selectHint")}</p>
              <div className="inline-flex gap-0.5 rounded-md border border-border p-0.5">
                {AGENTS.map((a) => (
                  <button
                    key={a.id}
                    type="button"
                    aria-pressed={selected.includes(a.id)}
                    // Single-select by default (one CLI = one click); in multi mode a
                    // click toggles membership so several CLIs can be picked.
                    onClick={() => (multiMode ? toggleAgent(a.id) : setSelected([a.id]))}
                    className={cn(
                      "cursor-pointer rounded px-2.5 py-1 text-xs font-medium transition-colors",
                      selected.includes(a.id)
                        ? "bg-foreground text-background"
                        : "text-muted-foreground hover:text-foreground",
                    )}
                  >
                    {a.label}
                  </button>
                ))}
              </div>
              <label className="flex cursor-pointer items-center gap-2 text-xs text-muted-foreground">
                <Checkbox
                  // Soften the component's default rounded-none (override via cn merge).
                  className="rounded-sm"
                  checked={multiMode}
                  // Turning multi off collapses back to a single CLI (keep the first).
                  onCheckedChange={(checked) => {
                    setMultiMode(checked === true)
                    if (!checked) setSelected((prev) => prev.slice(0, 1))
                  }}
                />
                {t("agentConnectGuide.multiToggle")}
              </label>
              <div className="space-y-1">
                <label className="flex cursor-pointer items-center gap-2 text-xs text-muted-foreground">
                  <Checkbox
                    className="rounded-sm"
                    checked={bypassMode}
                    onCheckedChange={(checked) => setBypassMode(checked === true)}
                  />
                  {t("agentConnectGuide.bypassToggle")}
                </label>
                {/* On by default, so the hint explains what UNCHECKING costs - the
                    decision the reader is actually facing. */}
                <p className="pl-6 text-[11px] leading-snug text-muted-foreground/80">
                  {t("agentConnectGuide.bypassHint")}
                </p>
              </div>
              <div className="space-y-1">
                <p className="text-xs text-muted-foreground">{t("agentConnectGuide.muxLabel")}</p>
                <div className="inline-flex gap-0.5 rounded-md border border-border p-0.5">
                  {(["tmux", "herdr"] as const).map((m) => (
                    <button
                      key={m}
                      type="button"
                      aria-pressed={multiplexer === m}
                      onClick={() => setMultiplexer(m)}
                      className={cn(
                        "cursor-pointer rounded px-2.5 py-1 text-xs font-medium transition-colors",
                        multiplexer === m
                          ? "bg-foreground text-background"
                          : "text-muted-foreground hover:text-foreground",
                      )}
                    >
                      {t(`agentConnectGuide.mux${m === "tmux" ? "Tmux" : "Herdr"}` as Parameters<typeof t>[0])}
                    </button>
                  ))}
                </div>
                {/* Both options carry a hint, because the choice is not "default versus
                    the one that needs explaining" - picking tmux is why setup has two
                    steps, and that is worth knowing before choosing it. Each says what
                    follows from the choice rather than naming a requirement. */}
                <p className="text-[11px] leading-snug text-muted-foreground/80">
                  {multiplexer === "herdr"
                    ? t("agentConnectGuide.muxHerdrHint")
                    : t("agentConnectGuide.muxTmuxHint")}
                </p>
              </div>
            </div>

            {(() => {
              const url = `${base}/mcp/${connectCode}?part=${part}`
              // Selected CLIs in canonical order; the first one is launched at the end.
              const clis = AGENTS.filter((a) => selected.includes(a.id)).map((a) => a.id)
              const multi = clis.length > 1
              // Unique tmux session per project+part so a shared part name (e.g.
              // "main") across projects doesn't collide on the tmux server.
              const session = `${projectSlug}-${part}`
              // Block 1 creates + attaches the tmux session (alone - `tmux new`
              // steals the terminal, so nothing can follow it in one paste).
              const tmuxCmd = `tmux new -s ${session}`
              // Block 2 runs INSIDE that session: register + set up every selected CLI,
              // start ONE pager in the background, then launch the first CLI in the
              // foreground - all in one paste, so no second terminal is needed. The
              // pager wakes whichever CLI is in front via `tmux send-keys`.
              const insideLines: string[] = clis.includes("codex") ? [`export RELAYROOM_TOKEN="<REDACTED>"`] : []
              for (const cli of clis) insideLines.push(mcpAddCommand(cli, "relayroom", url, token))
              // `--multiplexer herdr` is what lets init run at all on a herdr machine.
              // init guards on being inside a tmux session and refuses otherwise,
              // writing no config - after which `hooks install` has no --code and
              // ./rr.sh does not exist, so the rest of this block cannot complete. A
              // herdr worktree legitimately has no tmux session, and this flag is the
              // exemption. The guard gained it in 0.8.1; before that this block was
              // correct, which is why it emitted a working sequence and then quietly
              // stopped doing so without anything here changing.
              //
              // NOT written for tmux. Absence means tmux, and the field is intent:
              // rollback reads "nobody chose" and "someone chose tmux" differently, so
              // writing it here would spend that distinction on every default install.
              const muxFlag = multiplexer === "herdr" ? " --multiplexer herdr" : ""
              insideLines.push(
                // One init wires RELAYROOM.md + each CLI's instruction file (CSV).
                // Pass --server so init fetches RELAYROOM.md from THIS hub (matching the
                // mcp add URL); without it, init falls back to localhost and 404s on a
                // remote/LAN deployment.
                `${CLI_CMD} init --code ${connectCode} --part ${part} --target ${session} --agent ${clis.join(",")} --token ${token} --server ${base}${muxFlag}`,
              )
              for (const cli of clis) insideLines.push(`${CLI_CMD} hooks install --agent ${cli}`)
              // The last line differs by multiplexer, and it is a different VERB rather
              // than the same one with a flag.
              //
              // tmux: `./rr.sh launch` execs the CLI in the pane the reader is already
              // sitting in - the one block 1 created. It creates nothing itself, which
              // is exactly why block 1 has to exist and has to be pasted alone (`tmux
              // new` takes the terminal, so nothing can follow it in one paste).
              //
              // herdr: `./rr.sh up --use-herdr` asks herdr for this worktree's
              // workspace, puts the agent in it, and starts the pager in herdr mode.
              // Creation is inside `up`, so there is nothing to create beforehand and
              // no pane the paste has to happen inside - which collapses the two blocks
              // into one. Using `launch` here would exec the CLI in the reader's own
              // terminal and never open a herdr workspace at all.
              //
              // The flag only needs to appear once: it persists `multiplexer` into the
              // worktree config, so a later bare `up` keeps the choice.
              const byp = bypassMode ? " --bypass" : ""
              insideLines.push(
                multiplexer === "herdr" ? `./rr.sh up${byp} --use-herdr` : `./rr.sh launch${byp}`,
              )
              const insideCmd = insideLines.join("\n")
              return (
                <div className="space-y-3">
                  {/* No tmux block under herdr. Leaving it in would have the reader
                      create a session that nothing then uses, and the agent would come
                      up in a herdr workspace while an empty tmux session sat behind it
                      looking like the place to attach. */}
                  {multiplexer === "tmux" && (
                    <CmdBlock label={t("agentConnectGuide.step1Label")} command={tmuxCmd} />
                  )}
                  <CmdBlock
                    label={
                      multiplexer === "herdr"
                        ? t("agentConnectGuide.herdrStepLabel")
                        : t("agentConnectGuide.step2Label")
                    }
                    hint={
                      multiplexer === "herdr"
                        ? multi
                          ? t("agentConnectGuide.herdrStepHintMulti")
                          : t("agentConnectGuide.herdrStepHint")
                        : multi
                          ? t("agentConnectGuide.step2HintMulti")
                          : t("agentConnectGuide.step2Hint")
                    }
                    command={insideCmd}
                  />
                  {multi && (
                    <div className="space-y-2 rounded-md border border-amber-300/50 bg-amber-50/60 px-3 py-2.5 text-xs dark:border-amber-900/50 dark:bg-amber-950/20">
                      <p className="flex items-center gap-1.5 font-medium text-amber-900 dark:text-amber-200">
                        <InfoIcon className="h-3.5 w-3.5 shrink-0 text-amber-600 dark:text-amber-400" />
                        {t("agentConnectGuide.handoffTitle")}
                      </p>
                      <p className="text-amber-800/90 dark:text-amber-200/80">{t("agentConnectGuide.handoffNote")}</p>
                      <p className="text-amber-800/90 dark:text-amber-200/80">{t("agentConnectGuide.switchHint")}</p>
                    </div>
                  )}
                </div>
              )
            })()}

            <div className="flex items-start gap-2 rounded-md border border-amber-300/50 bg-amber-50/60 px-3 py-2.5 text-xs dark:border-amber-900/50 dark:bg-amber-950/20">
              <InfoIcon className="mt-0.5 h-3.5 w-3.5 shrink-0 text-amber-600 dark:text-amber-400" />
              <p className="text-amber-800 dark:text-amber-200">{t("agentConnect.folderNote")}</p>
            </div>
            <Button variant="outline" className="w-full" onClick={() => setOpen(false)}>
              {t("agentConnect.closeButton")}
            </Button>
          </div>
        )}
      </DialogContent>
    </Dialog>
  )
}

/** A labeled, copy-paste command block (its own copy state). */
function CmdBlock({ label, hint, command }: { label: string; hint?: string; command: string }) {
  const [copied, setCopied] = useState(false)
  return (
    <div className="space-y-1">
      <p className="text-xs font-medium text-foreground">{label}</p>
      {hint && <p className="text-[11px] text-muted-foreground">{hint}</p>}
      {/* Copy button overlays the top-right of the code (no reserved flex column, so
          long multi-line commands don't leave an empty gap beside the button). The
          code reserves right padding so the first line never runs under it. */}
      <div className="relative rounded border bg-muted/50">
        <code className="block whitespace-pre-wrap break-all p-2 pr-10 font-mono text-xs">{command}</code>
        <Button
          variant="ghost"
          size="sm"
          onClick={async () => {
            try {
              await navigator.clipboard.writeText(command)
              setCopied(true)
              setTimeout(() => setCopied(false), 2000)
            } catch {
              /* ignore */
            }
          }}
          className="absolute right-1.5 top-1.5 h-7 w-7 bg-muted/80 p-0 backdrop-blur"
          aria-label="Copy command"
        >
          {copied ? <CheckIcon className="h-4 w-4 text-emerald-600" /> : <CopyIcon className="h-4 w-4" />}
        </Button>
      </div>
    </div>
  )
}

