async function seedUser(id: string, name = id): Promise<void> {
  await db
    .insert(better_auth_user)
    .values({ id, name, email: `${id}@test.local`, emailVerified: true })
    .onConflictDoNothing()
}

async function seedOrg(id: string): Promise<void> {
