/**
 * The attest secret: <REDACTED> it (when off) or rotate it (when on), and show the
 * plaintext exactly once - the single moment it exists in the response.
 *
 * The plaintext lives only in component state, set from the action's return and
 * cleared when the owner dismisses it. It is never a prop, never refetched: there
 * is no read path that carries it, so a reload shows only the key id.
 */
export function AttestSecretCard({ projectId, keyId, prevKeyId, prevExpiresLabel }: Props) {
  const t = useTranslations("project")
  const router = useRouter()
  const { confirm, confirmDialog } = useConfirm()
  const [pending, setPending] = useState(false)
  const [minted, setMinted] = useState<{ secret: <REDACTED> keyId: string } | null>(null)
  const [copied, setCopied] = useState(false)

  const enabled = keyId !== null

  async function onRotate(mode: RotationMode = "hygiene") {
    const revoking = mode === "revoke"
    const ok = await confirm({
      title: revoking
        ? t("knowledgeAttest.revokeConfirmTitle")
        : enabled
          ? t("knowledgeAttest.rotateConfirmTitle")
          : t("knowledgeAttest.generateConfirmTitle"),
      description: revoking
        ? t("knowledgeAttest.revokeConfirmBody")
        : enabled
          ? t("knowledgeAttest.rotateConfirmBody")
          : t("knowledgeAttest.generateConfirmBody"),
      destructive: revoking,
    })
    if (!ok) return

    setPending(true)
    const request = rotateAttestSecret(projectId, mode).then((res) => {
      if (!res.result) throw new Error(res.message ?? t("knowledgeAttest.rotateFailed"))
      return res
    })
    toast.promise(request, {
      loading: revoking ? t("knowledgeAttest.revokePending") : t("knowledgeAttest.rotatePending"),
      success: (res) => {
        setMinted({ secret: <REDACTED> keyId: res.item.keyId })
        setCopied(false)
        return revoking ? t("knowledgeAttest.revokeDone") : t("knowledgeAttest.rotateDone")
      },
      error: (err: unknown) =>
        err instanceof Error ? err.message : t("knowledgeAttest.rotateFailed"),
    })
    await request.catch(() => {})
    setPending(false)
  }

  async function copySecret() {
    if (!minted) return
    try {
      await navigator.clipboard.writeText(minted.secret)
      setCopied(true)
    } catch {
      // Clipboard can be denied; the value is on screen to copy by hand.
    }
  }

  function dismissSecret() {
    // Refresh so the (now-current) key id renders from the server, then drop the
    // plaintext from memory. After this it is unrecoverable, by design.
    setMinted(null)
    router.refresh()
  }

  return (
    <section className="space-y-3 rounded-lg border border-border p-4">
      {confirmDialog}

      <div className="flex items-start gap-3">
        <KeyRoundIcon className="mt-0.5 h-5 w-5 shrink-0 text-muted-foreground" />
        <div className="flex-1">
          <h2 className="text-sm font-semibold">
            {enabled ? t("knowledgeAttest.enabledTitle") : t("knowledgeAttest.disabledTitle")}
          </h2>
          {!enabled && (
            <p className="mt-1 text-sm text-muted-foreground">{t("knowledgeAttest.disabledBody")}</p>
          )}
          {enabled && (
            <dl className="mt-2 space-y-1 text-xs">
              <div className="flex items-center gap-2">
                <dt className="text-muted-foreground">{t("knowledgeAttest.currentKeyLabel")}</dt>
                <dd className="font-mono">{keyId}</dd>
              </div>
              {prevKeyId && prevExpiresLabel && (
                <div className="flex items-center gap-2">
                  <dt className="text-muted-foreground">{t("knowledgeAttest.prevKeyLabel")}</dt>
                  <dd className="font-mono">{prevKeyId}</dd>
                  <dd className="text-muted-foreground">
                    {t("knowledgeAttest.prevKeyGrace", { expires: prevExpiresLabel })}
                  </dd>
                </div>
              )}
            </dl>
          )}
        </div>
        <Button size="sm" variant="outline" onClick={() => onRotate("hygiene")} disabled={pending}>
          {pending ? (
            <Loader2Icon className="mr-1 h-3.5 w-3.5 animate-spin" />
          ) : enabled ? (
            <RotateCwIcon className="mr-1 h-3.5 w-3.5" />
          ) : (
            <KeyRoundIcon className="mr-1 h-3.5 w-3.5" />
          )}
          {enabled ? t("knowledgeAttest.rotateButton") : t("knowledgeAttest.generateButton")}
        </Button>
      </div>

      {/* Incident path. Separated from the routine rotation above, in destructive
          tone, because it breaks running CI on purpose - and scoped honestly: it
          stops future misuse, it does not undo promotions the leaked key already
          made. Only offered when there is a live secret to revoke. */}
      {enabled && (
        <div className="rounded-md border border-destructive/30 bg-destructive/5 p-3">
          <div className="flex items-start gap-2">
            <ShieldAlertIcon className="mt-0.5 h-4 w-4 shrink-0 text-destructive" />
            <div className="min-w-0 flex-1">
              <h3 className="text-xs font-semibold text-destructive">
                {t("knowledgeAttest.revokeTitle")}
              </h3>
              <p className="mt-0.5 text-xs text-muted-foreground">
                {t("knowledgeAttest.revokeBody")}
              </p>
              <p className="mt-1 text-xs text-muted-foreground">
                {t("knowledgeAttest.revokeScopeNote")}
              </p>
            </div>
            <Button
              size="sm"
              variant="destructive"
              onClick={() => onRotate("revoke")}
              disabled={pending}
            >
              {pending ? (
                <Loader2Icon className="mr-1 h-3.5 w-3.5 animate-spin" />
              ) : (
                <ShieldAlertIcon className="mr-1 h-3.5 w-3.5" />
              )}
              {t("knowledgeAttest.revokeButton")}
            </Button>
          </div>
        </div>
      )}

      {/* One-time secret reveal. Present only between the mint and its dismissal. */}
      {minted && (
        <div className="space-y-2 rounded-md border border-amber-300/60 bg-amber-50/60 p-3 dark:border-amber-900/50 dark:bg-amber-950/20">
          <p className="text-sm font-medium text-amber-900 dark:text-amber-200">
            {t("knowledgeAttest.secretShownTitle")}
          </p>
          <p className="text-xs text-amber-800/80 dark:text-amber-200/70">
            {t("knowledgeAttest.secretShownBody")}
          </p>
          <div className="flex items-center gap-2">
            <code className="min-w-0 flex-1 truncate rounded bg-background px-2 py-1.5 font-mono text-xs">
              {minted.secret}
            </code>
            <Button size="sm" variant="outline" onClick={copySecret}>
              {copied ? <CheckIcon className="mr-1 h-3.5 w-3.5" /> : <CopyIcon className="mr-1 h-3.5 w-3.5" />}
              {copied ? t("knowledgeAttest.secretCopied") : t("knowledgeAttest.secretCopy")}
            </Button>
          </div>
          <Button size="sm" onClick={dismissSecret}>
            {t("knowledgeAttest.secretDismiss")}
          </Button>
        </div>
      )}
    </section>
  )
}

import { headers } from "next/headers"
import { redirect } from "next/navigation"
import { cache } from "react"
import { and, count, eq, sql, type AnyColumn, type SQL } from "drizzle-orm"
import { auth } from "./auth"
import { db } from "./db"
import {
  better_auth_user,
  better_auth_member,
  better_auth_invitation,
} from "@relayroom/db/auth-schema"
import { projects, projectAccess } from "@relayroom/db/schema"
import { decideProjectAccess, type ProjectAccessLevel } from "@relayroom/shared"
import { SIGN_IN_PATH, PENDING_PATH } from "@/constants/service"
import { getErrorTranslations } from "./action-i18n"

export type Session = Awaited<ReturnType<typeof auth.api.getSession>>

export const getServerSession = cache(async () => {
  return auth.api.getSession({ headers: await headers() })
})

export async function requireSession() {
  const session = await getServerSession()
  if (!session) redirect(SIGN_IN_PATH)
  return session
}

/**
 * Guard for the dashboard. Requires an authenticated session AND an approved
 * role/membership.
 *
 * Approved if:
 *   - role === 'admin', OR
 *   - the user is a member of at least one organization (accepted invitation)
 *
 * Non-members (stray accounts) are redirected to /account/pending.
 * Public sign-up is now closed (disableSignUp: true in auth.ts), so stray
 * accounts should not arise in normal usage.
 */
export async function requireDashboardAccess() {
  const session = await requireSession()
  const role = (session.user as { role?: string }).role

  if (role === "admin") return session

  // Check org membership
  const [row] = await db
    .select({ n: count() })
    .from(better_auth_member)
    .where(eq(better_auth_member.userId, session.user.id))

  if ((row?.n ?? 0) > 0) return session

  redirect(PENDING_PATH)
}

/**
 * Whether at least one admin exists. This is the predicate that gates the one-time
 * bootstrap: setup stays reachable until an admin actually exists, so a stranded
 * "users-but-no-admin" install (e.g. signup succeeded but promotion failed) can self-heal
 * instead of being permanently locked out.
 */
export const adminExists = cache(async () => {
  const [row] = await db
    .select({ n: count() })
    .from(better_auth_user)
    .where(eq(better_auth_user.role, "admin"))
  return (row?.n ?? 0) > 0
})

// ── Organization helpers ─────────────────────────────────────────────────────

/**
 * List all organizations the current user belongs to.
 * Returns [] if the user has no session or no memberships.
 */
export const getOrganizations = cache(async () => {
  try {
    const result = await auth.api.listOrganizations({ headers: await headers() })
    return result ?? []
  } catch {
    return []
  }
})

/**
 * Fetch the full active organization (with members list) for server components.
 * Returns null if there is no active organization.
 */
export const getActiveOrganization = cache(async () => {
  try {
    const result = await auth.api.getFullOrganization({ headers: await headers() })
    return result ?? null
  } catch {
    return null
  }
})

/**
 * The current user's role in their active organization, or null if there is no
 * session / no active org / no membership. Resolved from better_auth_member by
 * (activeOrganizationId, userId).
 */
export const getActiveOrgRole = cache(async (): Promise<string | null> => {
  const session = await getServerSession()
  if (!session) return null
  const activeOrgId = (session.session as { activeOrganizationId?: string })
    .activeOrganizationId
  if (!activeOrgId) return null

  const [row] = await db
    .select({ role: better_auth_member.role })
    .from(better_auth_member)
    .where(
      and(
        eq(better_auth_member.organizationId, activeOrgId),
        eq(better_auth_member.userId, session.user.id),
      ),
    )
  return row?.role ?? null
})

/** Whether the current user manages the active org (owner or admin). */
export const isActiveOrgManager = cache(async (): Promise<boolean> => {
  const role = await getActiveOrgRole()
  return role === "owner" || role === "admin"
})

/**
 * List pending invitations for the active organization.
 *
 * SECURITY: invitation ids are account-claiming links — anyone with the id can
 * create the invitee's account. better-auth's listInvitations returns invites to
 * ANY member, so we additionally gate this on the caller being an owner/admin of
 * the active org. Non-managers get [] even if invitations exist.
 */
export const getActiveOrgInvitations = cache(async () => {
  if (!(await isActiveOrgManager())) return []
  try {
    const result = await auth.api.listInvitations({ headers: await headers() })
    // listInvitations returns ALL invitations (incl. accepted/canceled/expired).
    // The UI renders live copy/cancel controls, so only show truly-pending invites:
    // status === 'pending' AND not yet expired.
    const now = Date.now()
    return (result ?? []).filter(
      (inv) =>
        inv.status === "pending" && new Date(inv.expiresAt).getTime() > now,
    )
  } catch {
    return []
  }
})

// ── Org-scoped helpers (for viewing a specific org, not necessarily the active one) ──

/**
 * The current user's role in the given organization, or null if there is no
 * session / no membership in that org. Unlike getActiveOrgRole, this is scoped
 * to an explicit orgId so it works when viewing a non-active org.
 */
export const getOrgRole = cache(
  async (orgId: string): Promise<string | null> => {
    const session = await getServerSession()
    if (!session) return null

    const [row] = await db
      .select({ role: better_auth_member.role })
      .from(better_auth_member)
      .where(
        and(
          eq(better_auth_member.organizationId, orgId),
          eq(better_auth_member.userId, session.user.id),
        ),
      )
    return row?.role ?? null
  },
)

/** Whether the current user is a member of the given org (any role). */
export const isOrgMember = cache(async (orgId: string): Promise<boolean> => {
  return (await getOrgRole(orgId)) !== null
})

/** Whether the current user manages the given org (owner or admin). */
export const isOrgManager = cache(async (orgId: string): Promise<boolean> => {
  const role = await getOrgRole(orgId)
  return role === "owner" || role === "admin"
})

/**
 * Whether the given user is currently banned from the given project
 * (project_access.bannedAt is non-null). This is the AUTHORITATIVE project-scope ban
 * gate on the web side - mirror of the gate in mcp.ts resolveConnection. A project ban
 * must cut a member off on the dashboard too (reads, writes, live SSE), not just on the
 * agent bus, or the ban is merely cosmetic for anyone using the web UI. Returns false
 * for a user with no project_access row (not banned).
 */
export const isBannedFromProject = cache(
  async (projectId: string, userId: string): Promise<boolean> => {
    const [row] = await db
      .select({ bannedAt: projectAccess.bannedAt })
      .from(projectAccess)
      .where(
        and(
          eq(projectAccess.projectId, projectId),
          eq(projectAccess.userId, userId),
        ),
      )
      .limit(1)
    return row?.bannedAt != null
  },
)

/**
 * SQL predicate form of `isBannedFromProject`, negated: true for projects the
 * user is NOT banned from.
 *
 * `isBannedFromProject` answers for ONE known project, so it fits a page/action
 * gate that has already resolved which project it is about. It does not fit a
 * listing, where the project set is what the query is computing - checking it per
 * row means a round trip per row, and the rows must be filtered inside the query
 * anyway so that LIMIT and counts stay correct. This is the same rule expressed
 * where a list query can apply it.
 *
 * Pass the `project.id` column of the query being filtered.
 */
export function notBannedFromProject(
  projectIdColumn: AnyColumn | SQL,
  userId: string,
): SQL {
  return sql`not exists (
    select 1 from ${projectAccess}
    where ${projectAccess.projectId} = ${projectIdColumn}
      and ${projectAccess.userId} = ${userId}
      and ${projectAccess.bannedAt} is not null
  )`
}

/**
 * Authorize a project MUTATION by `project_access.level`, not merely org
 * membership (AC-1/AC-2). `requireOrgAccess`-style helpers only proved the caller
 * belonged to the active org, so any member - including a `readonly` grant - could
 * call updateProject/archiveProject/regenerateConnectCode/connectAgent. This
 * resolves the project's OWN organization (not the caller's "active org" tab),
 * confirms org membership there, rejects a project-scope ban, then requires the
 * caller's `project_access.level` to be at least `minLevel`.
 *
 * Org owners/admins are treated as effective project owners (mirrors
 * `requireProjectManage` in modules/project/member-actions.ts) so an org
 * owner/admin is never locked out of a project they administer just because
 * nobody granted them an explicit project_access row.
 *
 * Takes `userId` rather than resolving the session itself: callers already
 * hold a verified session (they call `getServerSession()` beforehand), and
 * keeping session resolution out of this function means it depends only on
 * its (mockable, cross-module) inputs in tests.
 *
 * The rule itself now lives in `decideProjectAccess` (@relayroom/shared), so the
 * MCP server can apply the same one. It could not import this function: this is
 * Next-bound - it resolves translations and uses the web app's db handle - which
 * is why a project-level gate was previously impossible to add server-side. What
 * stays here is everything that is web-specific: looking the facts up, and
 * turning a refusal into a translated message.
 */
export async function requireProjectAccess(
  userId: string,
  projectId: string,
  minLevel: ProjectAccessLevel,
): Promise<
  | { ok: true; orgId: string; level: ProjectAccessLevel }
  | { ok: false; message: string }
> {
  const t = await getErrorTranslations()

  const [project] = await db
    .select({ id: projects.id, organizationId: projects.organizationId })
    .from(projects)
    .where(eq(projects.id, projectId))
    .limit(1)
  if (!project) return { ok: false, message: t("project.notFound") }

  // The grant row carries both facts the decision needs about this project, so
  // it is read once: a ban and a level taken from two reads could disagree.
  const [[member], [grant]] = await Promise.all([
    db
      .select({ role: better_auth_member.role })
      .from(better_auth_member)
      .where(
        and(
          eq(better_auth_member.organizationId, project.organizationId),
          eq(better_auth_member.userId, userId),
        ),
      )
      .limit(1),
    db
      .select({ level: projectAccess.level, bannedAt: projectAccess.bannedAt })
      .from(projectAccess)
      .where(and(eq(projectAccess.projectId, projectId), eq(projectAccess.userId, userId)))
      .limit(1),
  ])

  const decision = decideProjectAccess(
    { orgRole: member?.role, bannedAt: grant?.bannedAt, grantLevel: grant?.level },
    minLevel,
  )

  if (!decision.ok) {
    // The shared rule returns a reason, not copy - that is what lets the server
    // reuse it. Turning reasons into text is this layer's job.
    const message =
      decision.reason === "not_org_member"
        ? t("auth.noOrgAccess")
        : decision.reason === "banned"
          ? t("project.banned")
          : t("project.accessDenied")
    return { ok: false, message }
  }

  return { ok: true, orgId: project.organizationId, level: decision.level }
}

/**
 * List pending invitations for a SPECIFIC organization (the one being viewed).
 *
 * SECURITY: invitation ids are account-claiming links — anyone with the id can
 * create the invitee's account. So this is gated on the caller being an
 * owner/admin OF THAT org. Non-managers get [] even if invitations exist.
 *
 * Scoped directly against better_auth_invitation by organizationId so it is
 * correct regardless of which org is currently active in the session.
 */
export const getOrgInvitations = cache(async (orgId: string) => {
  if (!(await isOrgManager(orgId))) return []
  try {
    const rows = await db
      .select({
        id: better_auth_invitation.id,
        email: better_auth_invitation.email,
        role: better_auth_invitation.role,
        status: better_auth_invitation.status,
        expiresAt: better_auth_invitation.expiresAt,
      })
      .from(better_auth_invitation)
      .where(eq(better_auth_invitation.organizationId, orgId))

    // Only show truly-pending invites: status === 'pending' AND not yet expired.
    const now = Date.now()
    return rows.filter(
      (inv) =>
        inv.status === "pending" && new Date(inv.expiresAt).getTime() > now,
    )
  } catch {
    return []
  }
})

import { betterAuth } from "better-auth"
import { drizzleAdapter } from "better-auth/adapters/drizzle"
import { nextCookies } from "better-auth/next-js"
import { admin, organization, mcp } from "better-auth/plugins"
import * as authSchema from "@relayroom/db/auth-schema"
import { db } from "./db"
import { sendMail, escapeHtml } from "./email"
import { getNamespaceTranslations } from "./action-i18n"

// ── Plugin selection rationale (F6a) ────────────────────────────────────────
// We use `mcp()` (better-auth/plugins) which is a thin wrapper around
// `oidcProvider` that adds MCP OAuth 2.1-compliant endpoints:
//   - /.well-known/oauth-authorization-server  (RFC 8414 metadata)
//   - /.well-known/oauth-protected-resource    (RFC 9728 resource metadata)
//   - /mcp/authorize                           (authorization endpoint, PKCE)
//   - /mcp/token                               (token endpoint)
//   - /mcp/register                            (Dynamic Client Registration RFC 7591)
//   - /mcp/get-session                         (validate bearer → OAuthAccessToken)
//   - /oauth2/consent                          (consent POST endpoint)
//
// Both `mcp()` and `oidcProvider()` use the same DB schema
// (oauthApplication / oauthAccessToken / oauthConsent) — no migration needed.
//
// The `consentPage` option causes the authorize flow to redirect the browser to
// /account/oauth-consent?consent_code=<code>&client_id=<id>&scope=<scopes>
// when the `prompt=consent` parameter is present. Our consent page reads the
// project connect-code from the requested scope (format: project:<connect_code>),
// verifies the user's org membership, creates the agent + agent_connection
// (storing the access_token_id after the OAuth token is minted on approval),
// and then POSTs to /api/auth/oauth2/consent { accept: true, consent_code }.
//
// Docs: https://www.better-auth.com/docs/plugins/mcp

const baseUrl = process.env.BETTER_AUTH_URL ?? "http://localhost:48800"

export const auth = betterAuth({
  database: drizzleAdapter(db, { provider: "pg", schema: authSchema }),
  emailAndPassword: <REDACTED>
    enabled: true,
    // Public self-registration is closed.  Account creation is only possible
    // through:
    //   1. The one-time admin setup server action (auth.api.createUser, gated on
    //      !adminExists()).
    //   2. The accept-invitation server action (also uses auth.api.createUser).
    // Both bypass the public /api/auth/sign-up/email endpoint entirely.
    disableSignUp: true,
  },
  user: {
    modelName: "better_auth_user",
    additionalFields: {
      // Optional display nickname; settable via updateUser. Falls back to `name`.
      nickname: { type: "string", required: false, input: true },
    },
  },
  session: { modelName: "better_auth_session" },
  account: { modelName: "better_auth_account" },
  verification: { modelName: "better_auth_verification" },
  plugins: [
    admin(),
    organization({
      schema: {
        organization: { modelName: "better_auth_organization" },
        member: { modelName: "better_auth_member" },
        invitation: { modelName: "better_auth_invitation" },
      },
      // The dashboard guard only protects the UI; the create endpoint
      // (/api/auth/organization/create) is reachable by any session, including
      // self-registered pending users. Gate it at the API level: must be admin AND
      // no organization may exist yet. The Community Edition is single-workspace;
      // multiple organizations are an Enterprise feature.
      allowUserToCreateOrganization: async (user) => {
        if ((user as { role?: string }).role !== "admin") return false
        const existing = await db
          .select({ id: authSchema.better_auth_organization.id })
          .from(authSchema.better_auth_organization)
          .limit(1)
        return existing.length === 0
      },

      async sendInvitationEmail(data) {
        // data.id is a generated invitation id (no special chars) and baseUrl is
        // server-controlled, but escape the assembled URL too for defense in depth.
        const acceptUrl = `${baseUrl}/account/accept-invitation?id=${data.id}`
        const safeUrl = escapeHtml(acceptUrl)
        const inviterName = escapeHtml(
          data.inviter.user.name ?? data.inviter.user.email,
        )
        const orgName = escapeHtml(data.organization.name)
        // The invite is sent in the INVITER's locale: the recipient has no account
        // yet, so there is nothing to read a preference from. Carrying a locale on
        // the invitation row would fix that, but it is a schema change.
        // The <strong> wrapper is applied to the VALUES, not written into the
        // message: next-intl parses tags inside a message as rich-text and a plain
        // t() call then fails (FORMATTING_ERROR, renders the key). The values are
        // escaped above, so the only markup here is ours. The subject is not HTML,
        // so it keeps the raw org name.
        const t = await getNamespaceTranslations("mail")
        const strong = (s: string) => `<strong>${s}</strong>`
        await sendMail({
          to: data.email,
          subject: t("invitation.subject", { org: data.organization.name }),
          html: `
            <p>${t("invitation.greeting")}</p>
            <p>${t("invitation.intro", { inviter: strong(inviterName), org: strong(orgName) })}</p>
            <p>${t("invitation.cta")}</p>
            <p><a href="${safeUrl}">${safeUrl}</a></p>
            <p>${t("invitation.expiry")}</p>
          `,
        })
      },
    }),
    // F6a: MCP OAuth 2.1 provider (replaces bare oidcProvider from F4).
    // Schema is identical — uses the same better_auth_oauth_* tables.
    // nextCookies() MUST remain last (per better-auth docs).
    //
    // Token model (post-codex review): the issued access token authenticates the
    // USER (standard OIDC scopes only — openid/profile/email/offline_access). It is
    // NOT project-scoped. Project binding happens at the RESOURCE SERVER (F6b) via
    // the MCP URL `/mcp/<connect_code>`, where the agent_connection is get-or-created
    // and linked to access_token_id. Do not bind the project at OAuth time.
    mcp({
      loginPage: "/account/sign-in",
      oidcConfig: {
        // loginPage is required by OIDCOptions (used by the underlying oidcProvider).
        loginPage: "/account/sign-in",
        // Consent page — better-auth forwards ?consent_code=&client_id=&scope=.
        // The connect_code is carried separately (see oauth-consent/page.tsx) and
        // resolved there for the consent UX + org-membership check.
        consentPage: "/account/oauth-consent",
        // MCP OAuth 2.1 REQUIRES PKCE. requirePKCE=true rejects any authorize
        // request without code_challenge and forces the token endpoint to verify
        // the code_verifier (prevents auth-code interception). Option lives in
        // OIDCOptions (typed public API; the docs site omits it). Default is false.
        requirePKCE: true,
        // Standard OIDC scopes only (openid/profile/email/offline_access are added
        // automatically). No custom project scope — better-auth validates scopes
        // against this static list, so a dynamic project:<code> would always fail
        // invalid_scope. Project binding is the resource server's job (F6b).
        schema: {
          oauthApplication: { modelName: "better_auth_oauth_application" },
          oauthAccessToken: <REDACTED> modelName: "better_auth_oauth_access_token" },
          oauthConsent: { modelName: "better_auth_oauth_consent" },
        },
      },
    }),
    nextCookies(),
  ],
})

import { spawn } from "node:child_process"
import { Command, Option } from "commander"
import { connect } from "./connect"
import { installHook, printHook } from "./hooks"
import { init } from "./init"
import { runtimePath } from "./runtime"
import { DEFAULT_SERVER } from "./constants"
import { AGENT_IDS } from "./providers"
import { readConfig, writeConfig } from "./config"
import { CLI_VERSION } from "./version"
import { closePane, ensureWorkspace, findPane, herdrAgentName, herdrStatus, launchInPane, nameAgent } from "./herdr"
import { herdrCall } from "../runtime/herdr-client.mjs"
import { basename, resolve } from "node:path"

const agentOption = () =>
  new Option("--agent <agent>", "coding CLI to target")
    .choices(AGENT_IDS)
    .default("claude")

// Fields that `relayroom init` saves to .relayroom/config.json so other commands
// (and a compacted agent) can recover them without re-passing flags. Explicit
// flags win; then config; then the built-in default for the server.
function withConfig<T extends { code?: string; part?: string; target?: string; server?: string }>(
  opts: T,
): T & { server: string } {
  const cfg = readConfig(".")
  return {
    ...opts,
    code: opts.code ?? cfg.code,
    part: opts.part ?? cfg.part,
    target: opts.target ?? cfg.target,
    server: opts.server ?? cfg.server ?? DEFAULT_SERVER,
  }
}

function need(value: string | undefined, name: string): string {
  if (!value) {
    console.error(
      `error: --${name} is required (or run \`relayroom init --code <code>\` in this worktree first to save it to .relayroom/config.json)`,
    )
    process.exit(1)
  }
  return value
}

// Injected at build time by tsup from package.json, so `relayroom --version`
// always matches the published (lockstep) version - and matches the stamp `init`
// writes into rr.sh, which is what makes the staleness check meaningful.
const VERSION = CLI_VERSION

const program = new Command()
  .name("relayroom")
  .description("RelayRoom agent-side CLI - connect, pager, usage hook")
  .version(VERSION, "-v, --version", "print the RelayRoom CLI version")

// ── connect: wire a coding CLI into a project over MCP ──────────────────────────
program
  .command("connect")
  .description("Print (or run) the `<agent> mcp add` command for a RelayRoom project")
  .option("--code <connect_code>", "project connect code (default: from .relayroom/config.json)")
  .option("--part <part>", "this agent's part (e.g. backend, web, alice)")
  .addOption(agentOption())
  .option("--server <url>", "RelayRoom server base URL")
  .option("--name <name>", "MCP server name registered in the agent", "relayroom")
  .option("--run", "run the `mcp add` command instead of just printing it", false)
  .action((opts) => {
    const o = withConfig(opts)
    connect({ ...o, code: need(o.code, "code"), part: need(o.part, "part") })
  })

// ── init: write RELAYROOM.md + .relayroom/config.json into this worktree ─────────
program
  .command("init")
  .description("Set up this worktree: write RELAYROOM.md + save connection identity to .relayroom/config.json")
  .option("--code <connect_code>", "project connect code (first time only; then reused from .relayroom/config.json)")
  .option("--part <part>", "this agent's part (saved to .relayroom/config.json; reused on re-init)")
  .option("--target <tmux>", "tmux target for the pager (saved to .relayroom/config.json)")
  .option("--agent <agent>", "coding CLI(s) to target, comma-separated (claude|codex|agy)")
  .option("--token <token>", "bearer token, saved to .relayroom/config.json so rr.sh can re-run mcp add")
  // No Commander default: a baked-in default would overwrite a previously-saved
  // custom server on every re-init. init() resolves explicit flag -> saved config ->
  // built-in default instead.
  .option("--server <url>", "RelayRoom server base URL")
  .option("--dir <path>", "worktree directory", ".")
  .option("--no-reference", "do not add @RELAYROOM.md to the agent instruction file")
  .option("--no-tmux-check", "skip the guard that requires running inside a tmux session")
  .option("--multiplexer <name>", "tmux (default) or herdr - herdr worktrees need no tmux session")
  .option("--force", "re-point a worktree already registered as a different part/agent")
  .action((opts) => {
    if (opts.multiplexer !== undefined && opts.multiplexer !== "tmux" && opts.multiplexer !== "herdr") {
      console.error(`error: --multiplexer must be "tmux" or "herdr" (got "${opts.multiplexer}")`)
      process.exit(1)
    }
    return init(opts)
  })

// ── pager: wake an idle tmux session on new messages ────────────────────────────
program
  .command("pager")
  .description("Wake an idle Claude Code tmux session when RelayRoom messages arrive")
  .option("--code <connect_code>", "project connect code (default: from .relayroom/config.json)")
  .option("--part <part>", "this agent's part (default: from .relayroom/config.json)")
  .option("--target <tmux>", "tmux session, or session:window.pane, to wake (default: from .relayroom/config.json)")
  .option("--server <url>", "RelayRoom server base URL")
  .option("--debounce <ms>", "debounce window in milliseconds")
  .option("--token <token>", "bearer token, if the SSE endpoint requires auth")
  .action((opts) => {
    const o = withConfig(opts)
    // Headless delivery (codex/agy) spawns the CLI per wake instead of typing into a
    // tmux pane, so a tmux --target is not required. Every other mode keeps needing it.
    const cfg = readConfig(".")
    const headless = cfg.delivery === "headless"
    const args = [
      "--code", need(o.code, "code"),
      "--part", need(o.part, "part"),
      "--server", o.server,
    ]
    if (headless) {
      if (o.target) args.push("--target", o.target) // optional; used only for presence/status if present
      // The pager reads delivery/token from config.json too, but pass the CLI to spawn
      // explicitly (config.agent may be a comma list; the first entry is the primary).
      const cli = String(cfg.agent ?? "").split(",")[0]?.trim()
      if (cli) args.push("--agent-cli", cli)
    } else {
      args.push("--target", need(o.target, "target"))
    }
    if (o.debounce) args.push("--debounce", o.debounce)
    if (o.token) args.push("--token", o.token)
    // The pager is a long-lived foreground daemon; inherit stdio and mirror its
    // exit code so `relayroom pager` behaves exactly like running the script.
    const child = spawn(process.execPath, [runtimePath("relayroom-pager.mjs"), ...args], {
      stdio: "inherit",
    })
    // Forward kills to the child. rr.sh tracks THIS wrapper's pid; without forwarding,
    // `./rr.sh pager stop/restart` kills the wrapper but ORPHANS the node pager child
    // -> duplicate pagers pile up and storm the agent.
    for (const sig of ["SIGTERM", "SIGINT", "SIGHUP"] as const) process.on(sig, () => child.kill(sig))
    child.on("exit", (code) => process.exit(code ?? 0))
  })

// ── channel-server: Claude Code Channels wake server (stdio MCP) ────────────────
// Named `channel-server`, not `channel`, because 0.6.1 added `channel on|off` for the
// INTENT and commander throws at registration when two commands share a name - which
// killed every CLI invocation, including the launcher's, so no agent could start. The
// server keeps the renamed form rather than the intent giving way: `.mcp.json` spawns
// `relayroom-channel.mjs` directly on every worktree checked, so this wrapper had no
// callers, while `channel on|off` is already referenced by `rr.sh --channel`, the 0.6.1
// release notes, and config.ts. Renaming the one nobody calls costs nothing.
program
  .command("channel-server")
  .description("Run the RelayRoom Claude Channels server (stdio MCP; invoked by Claude via .mcp.json)")
  .option("--code <connect_code>", "project connect code (default: from .relayroom/config.json)")
  .option("--part <part>", "this agent's part (default: from .relayroom/config.json)")
  .option("--server <url>", "RelayRoom server base URL")
  .option("--token <token>", "bearer token, if the stream requires auth")
  .action((opts) => {
    const o = withConfig(opts)
    const args = [
      "--code", need(o.code, "code"),
      "--part", need(o.part, "part"),
      "--server", o.server,
    ]
    if (o.token) args.push("--token", o.token)
    // stdio is the MCP transport between Claude and the channel server; inherit it
    // verbatim (stdout carries JSON-RPC, stderr carries logs).
    const child = spawn(process.execPath, [runtimePath("relayroom-channel.mjs"), ...args], {
      stdio: "inherit",
    })
    // Forward kills so the channel server child dies with this wrapper (no orphans).
    for (const sig of ["SIGTERM", "SIGINT", "SIGHUP"] as const) process.on(sig, () => child.kill(sig))
    child.on("exit", (code) => process.exit(code ?? 0))
  })

// ── delivery: set the wake delivery mode in .relayroom/config.json ──────────────
program
  .command("delivery")
  .description("Set the wake delivery mode (channel|pager|headless) in .relayroom/config.json")
  .argument("<mode>", "channel, pager, or headless")
  .option("--dir <path>", "worktree directory", ".")
  .action((mode: string, opts: { dir: string }) => {
    if (mode !== "channel" && mode !== "pager" && mode !== "headless") {
      console.error(`error: mode must be "channel", "pager", or "headless" (got "${mode}")`)
      process.exit(1)
    }
    const path = writeConfig(opts.dir, { delivery: mode })
    console.log(`delivery=${mode} -> ${path}`)
  })

// ── herdr: the verbs rr.sh needs from the socket API ───────────────────────────
// One command with subcommands rather than several, because the shell calls them the
// same way and a single `herdr` namespace keeps the CLI's top level from growing a verb
// per multiplexer. Every one prints ONE line the script can read; nothing here is meant
// for a human to parse twice.
const herdrCmd = program
  .command("herdr")
  .description("herdr multiplexer helpers used by rr.sh (socket API)")

herdrCmd
  .command("status")
  .description("Whether herdr is usable here, and whether this worktree has a pane with an agent in it")
  .option("--dir <path>", "worktree directory", ".")
  .action(async (opts: { dir: string }) => {
    const st = await herdrStatus(resolve(opts.dir))
    // A shell reads fields, not prose: `key=value` on one line, and `usable` first so a
    // caller can branch on it without parsing the rest.
    console.log(
      [
        `usable=${st.usable}`,
        st.version ? `version=${st.version}` : "",
        `pane=${st.pane?.pane_id ?? "none"}`,
        `agent=${st.agent ? "yes" : "no"}`,
        st.reason ? `reason=${JSON.stringify(st.reason)}` : "",
      ].filter(Boolean).join(" "),
    )
    if (!st.usable) process.exit(1)
  })

herdrCmd
  .command("ensure")
  .description("Make sure a herdr workspace exists for this worktree (grouped under the repo when it is a git worktree)")
  .option("--dir <path>", "worktree directory", ".")
  .option("--label <label>", "workspace label")
  .action(async (opts: { dir: string; label?: string }) => {
    const dir = resolve(opts.dir)
    const cfg = readConfig(opts.dir)
    const label = opts.label ?? cfg.target ?? cfg.part ?? basename(dir)
    const { pane, created, grouped, why } = await ensureWorkspace(dir, label)
    console.log(
      `pane=${pane.pane_id} workspace=${pane.workspace_id} created=${created} grouped=${grouped}` +
        (grouped || !why ? "" : ` reason=${JSON.stringify(why)}`),
    )
  })

herdrCmd
  .command("launch")
  .description("Type a launch command into this worktree's pane and confirm an agent actually started")
  .argument("<command>", "the command to run in the pane")
  .option("--dir <path>", "worktree directory", ".")
  .action(async (command: string, opts: { dir: string }) => {
    const pane = await findPane(resolve(opts.dir))
    if (!pane) {
      console.error(`error: no herdr pane has cwd ${resolve(opts.dir)} - run \`relayroom herdr ensure\` first`)
      process.exit(1)
    }
    // Confirmed by watching the pane's processes, never by the response to send_keys:
    // herdr answers "ok" to input it delivered nowhere.
    const res = await launchInPane(pane.pane_id, command)
    // `deferred` is a real outcome, not a soft failure: the command is in the pane's
    // input and the shell runs it the moment this process exits. Reporting it as
    // started=false would send the caller down the "no agent appeared" path for a launch
    // that is about to happen, and reporting it as started=true would be a claim nobody
    // checked. It gets its own word.
    console.log(`pane=${pane.pane_id} started=${res.started} deferred=${res.deferred}`)
    if (!res.started && !res.deferred) process.exit(1)
  })

herdrCmd
  .command("close")
  .description("Close this worktree's herdr pane (the equivalent of killing its tmux session)")
  .option("--dir <path>", "worktree directory", ".")
  .action(async (opts: { dir: string }) => {
    const res = await closePane(resolve(opts.dir))
    if (!res.closed) { console.log("pane=none closed=false"); return }
    console.log(`pane=${res.pane} closed=true workspace=${res.workspace}`)
  })

herdrCmd
  .command("focus")
  .description("Bring this worktree's herdr workspace to the front")
  .option("--dir <path>", "worktree directory", ".")
  .action(async (opts: { dir: string }) => {
    const pane = await findPane(resolve(opts.dir))
    if (!pane) { console.error("error: no herdr pane for this worktree"); process.exit(1) }
    await herdrCall("workspace.focus", { workspace_id: pane.workspace_id })
    console.log(`workspace=${pane.workspace_id} focused=true`)
  })

herdrCmd
  .command("name")
  .description("Name this worktree's agent in herdr's agent list (the sidebar row)")
  .argument("[part]", "the part name (default: from .relayroom/config.json)")
  .option("--agent <id>", "the CLI running in the pane (default: from .relayroom/config.json)")
  .option("--dir <path>", "worktree directory", ".")
  .action(async (part: string | undefined, opts: { dir: string; agent?: string }) => {
    const dir = resolve(opts.dir)
    const cfg = readConfig(dir)
    const p = part ?? cfg.part ?? ""
    const agent = opts.agent ?? (cfg.agent ?? "").split(",")[0]
    if (!p) { console.error("error: no part given and none in .relayroom/config.json"); process.exit(1) }
    // Composed here, in the one place that knows herdr's naming rule, so a caller cannot
    // build a name that the server will refuse.
    const name = herdrAgentName(agent, p)
    const res = await nameAgent(dir, name)
    console.log(`named=${res.named} name=${name}${res.pane ? ` pane=${res.pane}` : ""}${res.why ? ` reason=${JSON.stringify(res.why)}` : ""}`)
  })

// ── channel: the INTENT to use Claude Code Channels (not the current mode) ──────
// Two commands, not one field, because the outage this comes from was a single field
// carrying both "what was asked for" and "what is running". `delivery` remains the
// measured mode; this is the standing wish, and only a human writes it.
program
  .command("channel")
  .description("Turn Claude Code Channels on or off for this worktree (intent; delivery reports the actual mode)")
  .argument("<state>", "on or off")
  .option("--dir <path>", "worktree directory", ".")
  .action((state: string, opts: { dir: string }) => {
    if (state !== "on" && state !== "off") {
      console.error(`error: state must be "on" or "off" (got "${state}")`)
      process.exit(1)
    }
    const path = writeConfig(opts.dir, { channel: state === "on" })
    console.log(`channel=${state === "on"} -> ${path}`)
    if (state === "on") {
      console.log("channels need a tmux pane (the launch stops on a confirmation prompt).")
      console.log("Run ./rr.sh up --restart for it to take effect.")
    }
  })

program
  .command("multiplexer")
  .description("Choose the multiplexer this worktree's part runs under (intent, persisted)")
  .argument("<name>", "tmux or herdr")
  .option("--dir <path>", "worktree directory", ".")
  .action((name: string, opts: { dir: string }) => {
    if (name !== "tmux" && name !== "herdr") {
      console.error(`error: multiplexer must be "tmux" or "herdr" (got "${name}")`)
      process.exit(1)
    }
    // Written even for "tmux", rather than deleting the key. Absent and "tmux" behave
    // identically at read time, but they are different FACTS: absent is "nobody has
    // chosen", "tmux" is "someone chose tmux" - which is what a rollback is. Losing that
    // distinction would make a rolled-back worktree indistinguishable from one that was
    // never migrated, and the rollback is exactly the moment somebody will ask.
    const path = writeConfig(opts.dir, { multiplexer: name })
    console.log(`multiplexer=${name} -> ${path}`)
  })

// ── hooks: manage the per-agent usage turn-end hook ─────────────────────────────
const hooks = program.command("hooks").description("Manage the RelayRoom usage hook")

hooks
  .command("install")
  .description("Wire the RelayRoom usage hook into the agent's config")
  .option("--code <connect_code>", "project connect code (default: from .relayroom/config.json)")
  .option("--part <part>", "this agent's part (default: from .relayroom/config.json)")
  .addOption(agentOption())
  .option("--server <url>", "RelayRoom server base URL")
  .option("--settings <path>", "config file to edit (default depends on --agent)")
  .option("--dir <path>", "worktree directory (the statusLine calls its rr.sh)", ".")
  .action((opts) => {
    const o = withConfig(opts)
    installHook({ ...o, code: need(o.code, "code"), part: need(o.part, "part") })
  })

hooks
  .command("print")
  .description("Print the usage hook config block (paste it into the agent config yourself)")
  .option("--code <connect_code>", "project connect code (default: from .relayroom/config.json)")
  .option("--part <part>", "this agent's part (default: from .relayroom/config.json)")
  .addOption(agentOption())
  .option("--server <url>", "RelayRoom server base URL")
  .action((opts) => {
    const o = withConfig(opts)
    printHook({ ...o, code: need(o.code, "code"), part: need(o.part, "part") })
  })

program.parseAsync(process.argv)

import { randomBytes } from 'node:crypto'
import { spawnSync } from 'node:child_process'
import { chmodSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { resolve, join } from 'node:path'
import { createInterface } from 'node:readline/promises'
import { stdin, stdout } from 'node:process'
import { renderCompose, renderEnv, type InstallConfig } from './templates'

declare const __INSTALL_VERSION__: string
const VERSION = typeof __INSTALL_VERSION__ === 'string' ? __INSTALL_VERSION__ : '0.0.0-dev'

const args = new Set(process.argv.slice(2))
const NON_INTERACTIVE = args.has('-y') || args.has('--yes')

function urlSafeSecret(bytes: number): string {
  // hex is URL-safe, so the password drops cleanly into a postgres:// URL.
  return randomBytes(bytes).toString('hex')
}
function authSecret(): string {
  return randomBytes(32).toString('base64')
}

function info(msg = '') {
  stdout.write(msg + '\n')
}

async function run() {
  info(`\n  RelayRoom installer v${VERSION}`)
  info('  Generates docker-compose.yml + .env to self-host RelayRoom from prebuilt images.\n')

  const rl = NON_INTERACTIVE ? null : createInterface({ input: stdin, output: stdout })
  const ask = async (q: string, def: string): Promise<string> => {
    if (!rl) return def
    const a = (await rl.question(`  ${q} [${def}]: `)).trim()
    return a === '' ? def : a
  }
  const askYesNo = async (q: string, def: boolean): Promise<boolean> => {
    if (!rl) return def
    const a = (await rl.question(`  ${q} (${def ? 'Y/n' : 'y/N'}): `)).trim().toLowerCase()
    if (a === '') return def
    return a === 'y' || a === 'yes'
  }

  try {
    const dirInput = await ask('Install directory', './relayroom')
    const dir = resolve(process.cwd(), dirInput)

    const version = await ask('Release version to pin', VERSION)
    const webUrl = await ask('Public dashboard URL (browsers)', 'http://localhost:48800')
    const serverBase = await ask('Public MCP server URL (agents)', 'http://localhost:48801')
    const webPort = await ask('Host port for the dashboard', '48800')
    const serverPort = await ask('Host port for the MCP server', '48801')

    let smtp: InstallConfig['smtp']
    if (await askYesNo('Configure SMTP for invitation emails now?', false)) {
      smtp = {
        host: await ask('SMTP host', ''),
        port: await ask('SMTP port', '587'),
        user: await ask('SMTP user', ''),
        pass: await ask('SMTP password', ''),
        from: await ask('From address', ''),
        secure: await ask('Use TLS (true/false)', 'false'),
      }
    }

    const config: InstallConfig = {
      version,
      webUrl,
      serverBase,
      webPort,
      serverPort,
      postgresPassword: <REDACTED>
      authSecret: <REDACTED>
      smtp,
    }

    const envPath = join(dir, '.env')
    mkdirSync(dir, { recursive: true })
    mkdirSync(join(dir, 'storage'), { recursive: true })
    writeFileSync(join(dir, 'docker-compose.yml'), renderCompose())

    // Write .env atomically with O_EXCL ('wx'): this fails rather than follow a
    // symlink or clobber an existing secrets file, closing the existsSync->write
    // TOCTOU window. On a real conflict, confirm before overwriting.
    const envBody = renderEnv(config)
    try {
      writeFileSync(envPath, envBody, { flag: 'wx', mode: 0o600 })
    } catch (e) {
      if ((e as NodeJS.ErrnoException).code !== 'EEXIST') throw e
      const overwrite = await askYesNo(`\n  ${envPath} already exists. Overwrite (regenerates secrets)?`, false)
      if (!overwrite) {
        info('\n  Aborted - left your existing .env untouched.')
        rl?.close()
        process.exitCode = 1
        return
      }
      writeFileSync(envPath, envBody, { flag: 'w', mode: 0o600 })
    }
    chmodSync(envPath, 0o600) // enforce 600 even on the overwrite (existing-file) path

    info('\n  Wrote:')
    info(`    ${join(dir, 'docker-compose.yml')}`)
    info(`    ${envPath}  (chmod 600 - holds generated secrets)`)
    info(`    ${join(dir, 'storage')}/`)

    const startNow = await askYesNo('\n  Start the stack now with `docker compose up -d`?', false)
    rl?.close()

    if (startNow) {
      info('\n  Setting storage ownership (uid 1000) and starting...')
      // storage must be writable by the container's node user (uid 1000). If chown
      // fails (needs privileges), do NOT start - the web container would boot unable
      // to write uploads. Stop and hand the user the exact commands instead.
      const storageDir = join(dir, 'storage')
      const chownRes = spawnSync('chown', ['-R', '1000:1000', storageDir], { stdio: 'inherit' })
      if (chownRes.status !== 0) {
        info(`\n  Could not set ${storageDir} to uid 1000 (needs privileges). Run:`)
        info(`    sudo chown -R 1000:1000 ${storageDir}`)
        info('    docker compose up -d')
        process.exitCode = 1
        return
      }
      const up = spawnSync('docker', ['compose', 'up', '-d'], { cwd: dir, stdio: 'inherit' })
      if (up.status !== 0) {
        info('\n  `docker compose up -d` did not complete. Run it yourself from the install dir.')
        process.exitCode = up.status ?? 1
        return
      }
    }

    info('\n  Next steps:')
    if (!startNow) {
      info(`    cd ${dirInput}`)
      info('    sudo chown -R 1000:1000 storage   # container runs as uid 1000')
      info('    docker compose up -d')
    }
    info(`    Open ${webUrl} and create the first admin account.`)
    info('    Docs: https://relayroom.dev/docs\n')
  } finally {
    rl?.close()
  }
}

/**
 * Upgrade an existing install: regenerate docker-compose.yml (which carries no
 * secrets) so compose-level changes from a new version land, and pin
 * RELAYROOM_VERSION in .env to this installer's version - everything else in .env
 * (secrets, URLs, SMTP) is preserved. `docker compose pull` alone only updates
 * images, never the compose file, so this fills that gap.
 */
function upgrade() {
  const dirArg = process.argv[3] && !process.argv[3].startsWith('-') ? process.argv[3] : '.'
  const dir = resolve(process.cwd(), dirArg)
  const composePath = join(dir, 'docker-compose.yml')
  const envPath = join(dir, '.env')

  info(`\n  RelayRoom installer v${VERSION} - upgrade`)
  if (!existsSync(composePath) || !existsSync(envPath)) {
    info(`\n  No RelayRoom install found in ${dir} (expected docker-compose.yml + .env).`)
    info('  Run this from the install directory, or pass it: npx @relayroom/install upgrade <dir>')
    process.exitCode = 1
    return
  }

  // Regenerate the compose (no secrets in it) to pick up compose-level changes.
  writeFileSync(composePath, renderCompose())
  // Pin RELAYROOM_VERSION to this installer's version, preserving the rest of .env.
  const env = readFileSync(envPath, 'utf8')
  const line = `RELAYROOM_VERSION=${VERSION}`
  const updated = /^RELAYROOM_VERSION=.*$/m.test(env)
    ? env.replace(/^RELAYROOM_VERSION=.*$/m, line)
    : env.replace(/\n*$/, `\n${line}\n`)
  writeFileSync(envPath, updated)

  info('\n  Updated:')
  info(`    ${composePath}  (regenerated for v${VERSION})`)
  info(`    ${envPath}  (RELAYROOM_VERSION=${VERSION}, other values kept)`)
  info('\n  Now pull the new images and restart:')
  info(`    cd ${dirArg}`)
  info('    docker compose pull')
  info('    docker compose up -d')
  info('')
}

if (process.argv[2] === 'upgrade') {
  upgrade()
} else {
  run().catch((err) => {
    info(`\n  Installer failed: ${err instanceof Error ? err.message : String(err)}`)
    process.exitCode = 1
  })
}

import { z } from 'zod'

// Canonical API response contract (ApiResult/ApiResultWithItem/ApiResultWithItems).
// All API returns (web modules, server actions, Hono server) use these.
export * from './api-types'

// Default RELAYROOM.md coordination playbook.
export * from './relayroom-md'

// Agent color presets (hex) + auto-resolver, shared with the web palette.
export * from './agent-colors'

// OAuth client identity for agent tokens - shared by the issuer (web) and the
// enforcer (server), which must not disagree on it.
export * from './oauth'

// Redaction rules: the stored shape, the detector catalogue, and the one function
// that turns configuration into patterns. Shared because the dashboard writes it and
// the server compiles it, and two copies of that rule is two rules.
export * from './redaction-rules'

// Applying the denylist. In shared because writers in three packages need it - see the
// file header for the count, which is kept in ONE place on purpose: this line said FOUR
// while the path union had five, and a cardinality repeated in three files is three
// chances to be stale.
export * from './redaction'
export * from './redaction-snapshot'

// The outcome of a lesson carried by `close` - a union so a refusal can never be read
// as a success. See the file header for why all eight refusals leave the close itself
// successful.
export * from './lesson-outcome'

// ── Attention signal ─────────────────────────────────────────────────────────

/**
 * Thread tag that marks a thread as needing a human (an agent is blocked or has
 * an explicit question for the operator). This is the ONLY signal the dashboard
 * bell counts. It is set by an agent via the `send`/`reply` MCP tools
 * (needsHuman: true) and cleared automatically when a human replies to the
 * thread, or manually dismissed from the inbox. Ambient "open thread" counts
 * (agent-driven, self-closing) are shown separately and never light up the bell.
 */
export const NEEDS_HUMAN_TAG = 'needs-human'

// ── Domain enums (text + zod validation — no pgEnum) ─────────────────────────

export const threadStatus = z.enum(['open', 'answered', 'closed', 'holding', 'canceled'])
export type ThreadStatus = z.infer<typeof threadStatus>

export const eventType = z.enum(['spawn', 'progress', 'complete', 'error', 'message'])
export type EventType = z.infer<typeof eventType>

export const agentRole = z.enum(['main', 'default'])
export type AgentRole = z.infer<typeof agentRole>

/**
 * `project_access.level`. These are the grants the dashboard actually issues, and
 * `owner` is load-bearing: it decides who may manage a project's members, and the
 * last-owner guards (demote, remove, ban) count rows at this level.
 *
 * `readonly_all` used to be listed here and never existed anywhere else: no UI
 * option, no label, no migration, no write path.
 */
export const projectAccessLevel = z.enum(['readonly', 'write', 'owner'])
export type ProjectAccessLevel = z.infer<typeof projectAccessLevel>

// Project authority as a pure decision (rank, org-manager rule, ban gate), so the
// dashboard and the MCP server answer "may this user do this?" the same way.
// Exported after the enum above because it builds on `ProjectAccessLevel`.
export * from './project-access'

export const connectionStatus = z.enum(['connected', 'expired', 'revoked'])
export type ConnectionStatus = z.infer<typeof connectionStatus>

// ── Usage (event.usage) ───────────────────────────────────────────────────────

export const eventUsage = z.object({
  input_tokens: <REDACTED>
  output_tokens: <REDACTED>
  cache_tokens: <REDACTED>
  model: z.string().optional(),
  cost_usd: z.number().optional(),
})
export type EventUsage = z.infer<typeof eventUsage>

// ── Message bus inputs ────────────────────────────────────────────────────────

export const sendMessageInput = z.object({
  project: z.string().min(1),
  from: z.string().min(1),
  to: z.array(z.string().min(1)).min(1),
  subject: z.string().min(1),
  body: z.string().min(1),
  tags: z.array(z.string()).optional(),
})
export type SendMessageInput = z.infer<typeof sendMessageInput>

export const replyInput = z.object({
  project: z.string().min(1),
  from: z.string().min(1),
  body: z.string().min(1),
  to: z.array(z.string().min(1)).optional(),
})
export type ReplyInput = z.infer<typeof replyInput>

export const ackInput = z.object({
  project: z.string().min(1),
  part: z.string().min(1),
})
export type AckInput = z.infer<typeof ackInput>

export const closeInput = z.object({
  project: z.string().min(1),
  status: z.enum(['answered', 'closed', 'holding', 'canceled']),
})
export type CloseInput = z.infer<typeof closeInput>

export const eventInput = z.object({
  project: z.string().min(1),
  part: z.string().min(1),
  type: eventType,
  detail: z.record(z.string(), z.unknown()).default({}),
  usage: eventUsage.optional(),
  parentEventId: z.string().optional(),
  spawnedAgentLabel: z.string().optional(),
  startedAt: z.string().datetime().optional(),
  endedAt: z.string().datetime().optional(),
})
export type EventInput = z.infer<typeof eventInput>

export const inboxItem = z.object({
  messageId: z.string(),
  threadId: z.string(),
  threadSubject: z.string(),
  fromPart: z.string().nullable(),
  body: z.string(),
  createdAt: z.string(),
})
export type InboxItem = z.infer<typeof inboxItem>

/** A new thread message / wake - drives live thread+event refresh on the dashboard. */
export type HubMessageEvent = {
  kind: 'message'
  /** Authoritative project id (used for tenant-safe SSE filtering). */
  projectId: string
  /** Project slug (display only; not unique across orgs). */
  project: string
  part: string
  threadId: string
  messageId: string
  subject: string
  fromPart: string
  /** Fencing token for the issued wake (phase 05 fills, phase 07 pager consumes). */
  wakeId?: string
}

/** A pager liveness beat - drives the live online/offline satellite-dish indicator. */
export type HubPagerEvent = {
  kind: 'pager'
  /** Authoritative project id (used for tenant-safe SSE filtering). */
  projectId: string
  /** Project slug (display only; not unique across orgs). */
  project: string
  /** The agent whose pager beat (used to key the dashboard indicator). */
  agentId: string
  part: string
  online: boolean
}

/** An agent marked a message read (ack) - drives live read-receipt refresh on the
 *  dashboard. A dedicated kind (not `message`) so pagers do NOT treat it as a wake. */
export type HubReadEvent = {
  kind: 'read'
  /** Authoritative project id (used for tenant-safe SSE filtering). */
  projectId: string
  /** Project slug (display only; not unique across orgs). */
  project: string
  /** The part that read the message (the reader). */
  part: string
  /** The message that was read. */
  messageId: string
}

/** An agent started composing a reply to a thread - drives a transient live "typing"
 *  indicator. A dedicated kind (not `message`) so pagers do NOT treat it as a wake. */
export type HubComposingEvent = {
  kind: 'composing'
  /** Authoritative project id (used for tenant-safe SSE filtering). */
  projectId: string
  /** Project slug (display only; not unique across orgs). */
  project: string
  /** The part that is composing. */
  part: string
  /** The thread the reply is being composed for. */
  threadId: string
}

/** An agent reported a provider rate-limit (or cleared one) - drives the live
 *  "limited until HH:MM" badge. A dedicated kind (not `message`) so pagers do NOT
 *  treat it as a wake. */
export type HubLimitedEvent = {
  kind: 'limited'
  /** Authoritative project id (used for tenant-safe SSE filtering). */
  projectId: string
  /** Project slug (display only; not unique across orgs). */
  project: string
  /** The part that is (or is no longer) rate-limited. */
  part: string
  /** ISO timestamp the limit lifts, or null when the limit was cleared. */
  limitedUntil: string | null
}

export type HubBusEvent = HubMessageEvent | HubPagerEvent | HubReadEvent | HubComposingEvent | HubLimitedEvent
